/** The Mughal Empire (History): 187 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"history-mughal-1","question":"Who founded the Mughal Empire in India?","options":["Akbar","Babur","Humayun","Aurangzeb"],"answer":1,"explanation":"Babur founded the Mughal Empire after the First Battle of Panipat in 1526.","difficulty":"easy","questionHi":"भारत में मुगल साम्राज्य की स्थापना किसने की?","optionsHi":["अकबर","बाबर","हुमायूँ","औरंगजेब"],"explanationHi":"बाबर ने 1526 में पानीपत के प्रथम युद्ध के बाद मुगल साम्राज्य की स्थापना की।"},
  {"id":"history-mughal-2","question":"The Taj Mahal was built by:","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb Alamgir"],"answer":2,"explanation":"Shah Jahan built it in Agra in memory of his wife Mumtaz Mahal.","difficulty":"easy","questionHi":"ताजमहल का निर्माण किसने करवाया था?","optionsHi":["अकबर","जहाँगीर","शाहजहाँ","औरंगजेब आलमगीर"],"explanationHi":"शाहजहाँ ने अपनी पत्नी मुमताज महल की याद में इसे आगरा में बनवाया।"},
  {"id":"history-mughal-3","question":"The Battle of Haldighati (1576) was fought between the Mughal army and:","options":["Rana Udai Singh II","Rana Sanga","Maharana Pratap","Hemu Vikramaditya"],"answer":2,"explanation":"Akbar’s forces, led by Man Singh, fought Maharana Pratap of Mewar at Haldighati in 1576. His father Udai Singh II had lost Chittor to Akbar in 1568, and Rana Sanga fought Babur at Khanwa in 1527.","difficulty":"moderate","questionHi":"हल्दीघाटी का युद्ध (1576) मुगल सेना और किसके बीच लड़ा गया था?","optionsHi":["राणा उदय सिंह द्वितीय","राणा सांगा","महाराणा प्रताप","हेमू विक्रमादित्य"],"explanationHi":"मान सिंह के नेतृत्व में अकबर की सेना ने 1576 में हल्दीघाटी में मेवाड़ के महाराणा प्रताप से युद्ध किया। उनके पिता उदय सिंह द्वितीय ने 1568 में चित्तौड़ अकबर के हाथों खो दिया था, और राणा सांगा ने 1527 में खानवा में बाबर से युद्ध किया था।"},
  {"id":"history-mughal-4","question":"Which Mughal emperor built Fatehpur Sikri?","options":["Babur","Humayun","Akbar","Shah Jahan"],"answer":2,"explanation":"Akbar built Fatehpur Sikri (c. 1571–85) near the hermitage of Shaikh Salim Chishti and marked his Gujarat victory with its Buland Darwaza. Shah Jahan tempts as the great builder, but his capital was Shahjahanabad in Delhi.","difficulty":"moderate","questionHi":"किस मुगल सम्राट ने फतेहपुर सीकरी का निर्माण करवाया?","optionsHi":["बाबर","हुमायूँ","अकबर","शाहजहाँ"],"explanationHi":"अकबर ने शेख सलीम चिश्ती की कुटिया के निकट फतेहपुर सीकरी (लगभग 1571–85) बनवाया और अपनी गुजरात विजय की स्मृति में इसका बुलंद दरवाजा बनवाया। शाहजहाँ महान निर्माता के रूप में भ्रमित करता है, परंतु उसकी राजधानी दिल्ली का शाहजहानाबाद थी।"},
  {"id":"history-mughal-5","question":"Din-i-Ilahi was started by:","options":["Babur","Akbar","Jahangir","Shah Jahan"],"answer":1,"explanation":"Akbar propounded Din-i-Ilahi in 1582 as a blend of ideas from several religions.","difficulty":"moderate","questionHi":"दीन-ए-इलाही की शुरुआत किसने की थी?","optionsHi":["बाबर","अकबर","जहाँगीर","शाहजहाँ"],"explanationHi":"अकबर ने 1582 में दीन-ए-इलाही चलाया, जो कई धर्मों के विचारों का मिश्रण था।"},
  {"id":"history-mughal-6","question":"The Second Battle of Panipat (1556) was fought between Akbar’s forces and:","options":["Ibrahim Lodi","Hemu","Rana Sanga","Sher Shah Suri"],"answer":1,"explanation":"Bairam Khan, leading Akbar’s army, defeated Hemu (Hem Chandra Vikramaditya).","difficulty":"hard","questionHi":"पानीपत का द्वितीय युद्ध (1556) अकबर की सेना और किसके बीच लड़ा गया था?","optionsHi":["इब्राहिम लोदी","हेमू","राणा सांगा","शेरशाह सूरी"],"explanationHi":"अकबर की सेना का नेतृत्व कर रहे बैरम खाँ ने हेमू (हेमचंद्र विक्रमादित्य) को पराजित किया।"},
  {"id":"history-mughal-7","question":"Who defeated Humayun and forced him into exile?","options":["Hemu Vikramaditya","Sher Shah Suri","Bahadur Shah of Gujarat","Bairam Khan"],"answer":1,"explanation":"Sher Shah Suri defeated Humayun at Chausa (1539) and Kannauj (1540), driving him into exile in Persia. Bahadur Shah of Gujarat is the trap: Humayun defeated him in 1535, not the other way round.","difficulty":"hard","questionHi":"हुमायूँ को पराजित करके निर्वासन के लिए किसने विवश किया?","optionsHi":["हेमू विक्रमादित्य","शेरशाह सूरी","गुजरात का बहादुर शाह","बैरम खाँ"],"explanationHi":"शेरशाह सूरी ने हुमायूँ को चौसा (1539) और कन्नौज (1540) में हराकर फारस में निर्वासन के लिए विवश कर दिया। गुजरात का बहादुर शाह भ्रम पैदा करने वाला विकल्प है: हुमायूँ ने उसे 1535 में हराया था, उसने हुमायूँ को नहीं।"},
  {"id":"history-mughal-8","question":"Who was Akbar’s regent during the early years of his reign?","options":["Abul Fazl","Bairam Khan","Raja Todar Mal","Raja Birbal"],"answer":1,"explanation":"Bairam Khan, Humayun's trusted general, ruled as Akbar's vakil and regent from 1556 until Akbar dismissed him in 1560. Abul Fazl, Todar Mal and Birbal rose only later, in Akbar's mature reign.","difficulty":"hard","questionHi":"अकबर के शासन के प्रारंभिक वर्षों में उसका संरक्षक (रीजेंट) कौन था?","optionsHi":["अबुल फजल","बैरम खाँ","राजा टोडरमल","राजा बीरबल"],"explanationHi":"हुमायूँ के विश्वस्त सेनापति बैरम खाँ ने 1556 से 1560 तक, जब तक अकबर ने उसे हटा नहीं दिया, अकबर के वकील और संरक्षक के रूप में शासन किया। अबुल फजल, टोडरमल और बीरबल अकबर के परिपक्व शासनकाल में ही प्रमुख बने।"},
  {"id":"history-mughal-9","question":"The Mansabdari system was introduced by:","options":["Babur","Akbar","Jahangir","Aurangzeb"],"answer":1,"explanation":"Akbar introduced the Mansabdari system to organise the nobility and army by ranks (mansabs).","difficulty":"very-hard","questionHi":"मनसबदारी प्रथा किसने शुरू की थी?","optionsHi":["बाबर","अकबर","जहाँगीर","औरंगजेब"],"explanationHi":"अकबर ने कुलीनों और सेना को पदों (मनसब) के आधार पर संगठित करने के लिए मनसबदारी प्रथा शुरू की।"},
  {"id":"history-mughal-10","question":"The Battle of Khanwa (1527) was fought between Babur and:","options":["Ibrahim Lodi","Rana Sanga","Hemu","Medini Rai"],"answer":1,"explanation":"Babur defeated Rana Sanga of Mewar at Khanwa, near Agra, in 1527.","difficulty":"very-hard","questionHi":"खानवा का युद्ध (1527) बाबर और किसके बीच लड़ा गया था?","optionsHi":["इब्राहिम लोदी","राणा सांगा","हेमू","मेदिनी राय"],"explanationHi":"बाबर ने 1527 में आगरा के निकट खानवा में मेवाड़ के राणा सांगा को पराजित किया।"},
  {"id":"history-mughal-11","question":"Which Mughal emperor reimposed the jizya tax in 1679?","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb"],"answer":3,"explanation":"Akbar had abolished jizya in 1564; Aurangzeb reimposed it in 1679.","difficulty":"very-hard","questionHi":"किस मुगल सम्राट ने 1679 में जजिया कर फिर से लगाया?","optionsHi":["अकबर","जहाँगीर","शाहजहाँ","औरंगजेब"],"explanationHi":"अकबर ने 1564 में जजिया समाप्त कर दिया था; औरंगजेब ने 1679 में इसे फिर से लगा दिया।"},
  {"id":"history-mughal-12","question":"The First Battle of Panipat (1526) was fought between Babur and:","options":["Rana Sanga of Mewar","Ibrahim Lodi","Hemu","Sher Shah Suri"],"answer":1,"explanation":"At Panipat in April 1526 Babur's artillery and tulughma tactics crushed Sultan Ibrahim Lodi, ending the Delhi Sultanate. Rana Sanga is the trap: Babur defeated him a year later at Khanwa (1527).","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"पानीपत का प्रथम युद्ध (1526) बाबर और किसके बीच लड़ा गया था?","optionsHi":["मेवाड़ का राणा सांगा","इब्राहिम लोदी","हेमू","शेरशाह सूरी"],"explanationHi":"अप्रैल 1526 में पानीपत में बाबर के तोपखाने और तुलुगमा रणनीति ने सुल्तान इब्राहिम लोदी को कुचल दिया, जिससे दिल्ली सल्तनत का अंत हो गया। राणा सांगा भ्रम पैदा करने वाला विकल्प है: बाबर ने उसे एक वर्ष बाद खानवा (1527) में हराया।"},
  {"id":"history-mughal-13","question":"Din-i-Ilahi, a syncretic faith, was propounded by:","options":["Babur","Akbar","Jahangir","Shah Jahan"],"answer":1,"explanation":"Akbar announced the Din-i-Ilahi (Tauhid-i-Ilahi) in 1582, after the Ibadat Khana debates, as a discipleship centred on himself rather than a new religion. Jahangir is the usual slip, but he did not continue it.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"समन्वयवादी धर्म दीन-ए-इलाही का प्रतिपादन किसने किया?","optionsHi":["बाबर","अकबर","जहाँगीर","शाहजहाँ"],"explanationHi":"इबादतखाना की बहसों के बाद अकबर ने 1582 में दीन-ए-इलाही (तौहीद-ए-इलाही) की घोषणा की, जो नया धर्म नहीं बल्कि स्वयं उसे केंद्र में रखकर बनाया गया शिष्यत्व था। जहाँगीर सामान्यतः होने वाली भूल है, पर उसने इसे आगे नहीं बढ़ाया।"},
  {"id":"history-mughal-14","question":"The Battle of Haldighati (1576) was fought between Akbar’s forces and:","options":["Rana Sanga","Rana Pratap","Rana Kumbha","Rana Udai Singh"],"answer":1,"explanation":"Man Singh led the Mughal army against Maharana Pratap of Mewar.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"हल्दीघाटी का युद्ध (1576) अकबर की सेना और किसके बीच लड़ा गया था?","optionsHi":["राणा सांगा","राणा प्रताप","राणा कुंभा","राणा उदय सिंह"],"explanationHi":"मान सिंह ने मुगल सेना का नेतृत्व करते हुए मेवाड़ के महाराणा प्रताप के विरुद्ध युद्ध किया।"},
  {"id":"history-mughal-15","question":"Which Mughal ruler’s reign is called the “Golden Age of Mughal architecture”, with the Taj Mahal and Red Fort built?","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb Alamgir"],"answer":2,"explanation":"Shah Jahan (1628–58) built the Taj Mahal, Red Fort and Jama Masjid.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"किस मुगल शासक का काल “मुगल स्थापत्य का स्वर्ण युग” कहलाता है, जिसमें ताजमहल और लाल किला बनाए गए?","optionsHi":["अकबर","जहाँगीर","शाहजहाँ","औरंगजेब आलमगीर"],"explanationHi":"शाहजहाँ (1628–58) ने ताजमहल, लाल किला और जामा मस्जिद बनवाए।"},
  {"id":"history-mughal-16","question":"Which Mughal emperor re-imposed the jizya tax on non-Muslims in 1679?","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb"],"answer":3,"explanation":"Akbar abolished the jizya in 1564, and Aurangzeb reimposed it in 1679 as part of his orthodox turn. Shah Jahan tempts because of his stricter later policies, but he never brought back the jizya.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"किस मुगल सम्राट ने 1679 में गैर-मुस्लिमों पर जजिया कर फिर से लगाया?","optionsHi":["अकबर","जहाँगीर","शाहजहाँ","औरंगजेब"],"explanationHi":"अकबर ने 1564 में जजिया समाप्त किया था और औरंगजेब ने अपनी रूढ़िवादी नीति के तहत 1679 में इसे फिर से लगा दिया। शाहजहाँ अपनी बाद की कठोर नीतियों के कारण भ्रम पैदा करता है, पर उसने जजिया कभी वापस नहीं लगाया।"},
  {"id":"history-mughal-17","question":"The Mughal emperor who was a prisoner of the Marathas and later of the British, and in whose reign the Battle of Buxar (1764) took place, was:","options":["Farrukhsiyar","Muhammad Shah","Shah Alam II","Bahadur Shah Zafar"],"answer":2,"explanation":"Shah Alam II fought at Buxar and granted the Diwani of Bengal to the Company in 1765.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"वह मुगल सम्राट कौन था जो मराठों और बाद में अंग्रेजों का बंदी रहा, और जिसके शासनकाल में बक्सर का युद्ध (1764) हुआ?","optionsHi":["फर्रुखसियर","मुहम्मद शाह","शाह आलम द्वितीय","बहादुर शाह जफर"],"explanationHi":"शाह आलम द्वितीय ने बक्सर में युद्ध किया और 1765 में बंगाल की दीवानी कंपनी को दे दी।"},
  {"id":"history-mughal-18","question":"The Second Battle of Panipat (1556) was fought between Akbar’s army, led by Bairam Khan, and:","options":["Ibrahim Lodi","Hemu","Sher Shah Suri","Rana Sanga"],"answer":1,"explanation":"At Panipat in November 1556 Bairam Khan's army defeated Hemu, Adil Shah Sur's general who had taken Delhi as 'Vikramaditya'; an arrow in the eye decided the battle. Ibrahim Lodi was Babur's opponent at the First Battle of Panipat in 1526.","difficulty":"hard","questionHi":"पानीपत का द्वितीय युद्ध (1556) बैरम खाँ के नेतृत्व वाली अकबर की सेना और किसके बीच लड़ा गया था?","optionsHi":["इब्राहिम लोदी","हेमू","शेरशाह सूरी","राणा सांगा"],"explanationHi":"नवंबर 1556 में पानीपत में बैरम खाँ की सेना ने हेमू को हराया, जो आदिल शाह सूर का सेनापति था और जिसने “विक्रमादित्य” की उपाधि लेकर दिल्ली पर अधिकार कर लिया था; आँख में तीर लगने से युद्ध का निर्णय हुआ। इब्राहिम लोदी 1526 में पानीपत के प्रथम युद्ध में बाबर का प्रतिद्वंद्वी था।"},
  {"id":"history-mughal-19","question":"Babur’s memoir, the Baburnama, was originally written in:","options":["Classical Persian","Arabic","Chagatai Turkish","Early Hindavi (Urdu)"],"answer":2,"explanation":"Babur wrote in his mother tongue, Chagatai Turkish; it was translated into Persian under Akbar.","difficulty":"hard","questionHi":"बाबर के संस्मरण बाबरनामा की मूल रचना किस भाषा में हुई थी?","optionsHi":["शास्त्रीय फारसी","अरबी","चगताई तुर्की","प्रारंभिक हिंदवी (उर्दू)"],"explanationHi":"बाबर ने अपनी मातृभाषा चगताई तुर्की में लिखा; अकबर के काल में इसका फारसी में अनुवाद हुआ।"},
  {"id":"history-mughal-20","question":"The Zabti (Dahsala) land revenue system under Akbar was developed by:","options":["Raja Birbal","Raja Todar Mal","Shaikh Abul Fazl","Raja Man Singh"],"answer":1,"explanation":"Raja Todar Mal measured land and fixed revenue on the average produce of ten years.","difficulty":"very-hard","questionHi":"अकबर के अधीन जब्ती (दहसाला) भू-राजस्व प्रणाली का विकास किसने किया?","optionsHi":["राजा बीरबल","राजा टोडरमल","शेख अबुल फजल","राजा मान सिंह"],"explanationHi":"राजा टोडरमल ने भूमि की पैमाइश करवाई और दस वर्षों की औसत उपज के आधार पर राजस्व निर्धारित किया।"},
  {"id":"history-mughal-21","question":"Consider: 1. The Buland Darwaza at Fatehpur Sikri commemorates Akbar’s Gujarat campaign. 2. Akbar’s Ibadat Khana was at Fatehpur Sikri. 3. Akbar abolished the pilgrimage tax. Which are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct; the pilgrimage tax went in 1563 and the jizya in 1564.","difficulty":"very-hard","questionHi":"विचार कीजिए: 1. फतेहपुर सीकरी का बुलंद दरवाजा अकबर के गुजरात अभियान की स्मृति में बना है। 2. अकबर का इबादतखाना फतेहपुर सीकरी में था। 3. अकबर ने तीर्थ यात्रा कर समाप्त कर दिया। इनमें से कौन-से कथन सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"तीनों कथन सही हैं; तीर्थ यात्रा कर 1563 में और जजिया 1564 में समाप्त किया गया।"},
  {"id":"history-mughal-22","question":"How many of these statements are correct? I. Sher Shah defeated Humayun at Chausa (1539) and Kannauj (1540). II. Sher Shah issued the silver coin called the rupiya. III. Sher Shah rebuilt and extended the road later called the Grand Trunk Road. IV. Humayun’s tomb was built by Shah Jahan.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Humayun’s tomb was built in Akbar’s reign, commissioned by Bega Begum.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. शेरशाह ने हुमायूँ को चौसा (1539) और कन्नौज (1540) में पराजित किया। II. शेरशाह ने “रुपिया” नामक चाँदी का सिक्का जारी किया। III. शेरशाह ने उस सड़क का पुनर्निर्माण और विस्तार करवाया जिसे बाद में ग्रैंड ट्रंक रोड कहा गया। IV. हुमायूँ का मकबरा शाहजहाँ ने बनवाया था।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। हुमायूँ का मकबरा अकबर के शासनकाल में बना था, जिसे बेगा बेगम ने बनवाया था।"},
  {"id":"history-mughal-23","question":"How many of these statements are correct? I. The Peacock Throne was made for Jahangir. II. Nadir Shah carried it away in 1761. III. Aurangzeb died in 1707.","options":["Only one","Only two","All three","None"],"answer":0,"explanation":"Only III is correct. The Peacock Throne (Takht-i-Taus) was made for Shah Jahan, and Nadir Shah carried it off after sacking Delhi in 1739; 1761 is the year of the Third Battle of Panipat.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. तख्त-ए-ताउस (मयूर सिंहासन) जहाँगीर के लिए बनाया गया था। II. नादिर शाह उसे 1761 में ले गया। III. औरंगजेब की मृत्यु 1707 में हुई।","optionsHi":["केवल एक","केवल दो","तीनों","कोई नहीं"],"explanationHi":"केवल III सही है। तख्त-ए-ताउस (मयूर सिंहासन) शाहजहाँ के लिए बना था, और नादिर शाह दिल्ली को लूटने के बाद उसे 1739 में ले गया; 1761 पानीपत के तृतीय युद्ध का वर्ष है।"},
  {"id":"history-mughal-24","question":"Arrange in chronological order: 1. Second Battle of Panipat 2. Battle of Khanwa 3. Battle of Haldighati 4. Battle of Chausa","options":["2-4-1-3","4-2-1-3","2-1-4-3","2-4-3-1"],"answer":0,"explanation":"Khanwa (1527), Chausa (1539), Second Panipat (1556), Haldighati (1576).","difficulty":"very-hard","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. पानीपत का द्वितीय युद्ध 2. खानवा का युद्ध 3. हल्दीघाटी का युद्ध 4. चौसा का युद्ध","optionsHi":["2-4-1-3","4-2-1-3","2-1-4-3","2-4-3-1"],"explanationHi":"खानवा (1527), चौसा (1539), पानीपत द्वितीय (1556), हल्दीघाटी (1576)।"},
  {"id":"history-mughal-25","question":"How many of these statements are correct? I. Akbar’s Mahzar (1579) let him decide between conflicting interpretations of Islamic law. II. Din-i-Ilahi was propagated by Jahangir. III. Akbar abolished the jizya in 1564.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Statements I and III are correct: the Mahzar (1579) let Akbar choose among conflicting rulings of the ulema, and he abolished the jizya in 1564. Din-i-Ilahi was Akbar's own order of 1582, not Jahangir's.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. अकबर के महजर (1579) ने उसे इस्लामी कानून की परस्पर विरोधी व्याख्याओं में से निर्णय लेने का अधिकार दिया। II. दीन-ए-इलाही का प्रचार जहाँगीर ने किया। III. अकबर ने 1564 में जजिया समाप्त कर दिया।","optionsHi":["केवल एक","केवल दो","तीनों","कोई नहीं"],"explanationHi":"कथन I और III सही हैं: महजर (1579) ने अकबर को उलेमा के परस्पर विरोधी निर्णयों में से चुनने का अधिकार दिया, और उसने 1564 में जजिया समाप्त किया। दीन-ए-इलाही अकबर का अपना 1582 का संप्रदाय था, जहाँगीर का नहीं।"},
  {"id":"history-mughal-26","question":"In the Mughal mansabdari system, the “sawar” rank showed:","options":["The officer's personal status and salary scale","The number of cavalrymen he had to maintain","The land revenue assigned to him","The number of elephants under his command"],"answer":1,"explanation":"Zat was the personal rank and salary; sawar was the number of horsemen the mansabdar had to keep.","difficulty":"very-hard","questionHi":"मुगल मनसबदारी प्रणाली में “सवार” पद क्या दर्शाता था?","optionsHi":["अधिकारी की व्यक्तिगत प्रतिष्ठा और वेतनमान","उसे जितने घुड़सवार रखने होते थे उनकी संख्या","उसे सौंपा गया भू-राजस्व","उसकी कमान में हाथियों की संख्या"],"explanationHi":"जात व्यक्तिगत पद और वेतन था; सवार वह संख्या थी जितने घुड़सवार मनसबदार को रखने होते थे।"},
  {"id":"history-mughal-27","question":"Arrange in chronological order: 1. Treaty of Purandar between Shivaji and Jai Singh 2. Battle of Samugarh 3. Jahangir’s marriage to Nur Jahan 4. Start of construction of the Taj Mahal","options":["3-4-2-1","3-2-4-1","4-3-2-1","3-4-1-2"],"answer":0,"explanation":"Nur Jahan’s marriage (1611), Taj Mahal begun (1632), Samugarh (1658, where Aurangzeb defeated Dara Shikoh), Treaty of Purandar (1665).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. शिवाजी और जय सिंह के बीच पुरंदर की संधि 2. सामूगढ़ का युद्ध 3. जहाँगीर का नूरजहाँ से विवाह 4. ताजमहल के निर्माण की शुरुआत","optionsHi":["3-4-2-1","3-2-4-1","4-3-2-1","3-4-1-2"],"explanationHi":"नूरजहाँ का विवाह (1611), ताजमहल का आरंभ (1632), सामूगढ़ (1658, जहाँ औरंगजेब ने दारा शिकोह को हराया), पुरंदर की संधि (1665)।"},
  {"id":"history-mughal-28","question":"How many of these statements are correct? I. Jahangir’s memoir is the Tuzuk-i-Jahangiri. II. The Ain-i-Akbari is the third volume of Faizi’s Akbarnama. III. Shah Jahan took the title Alamgir. IV. The Red Fort of Delhi was built by Akbar.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. The Akbarnama and Ain-i-Akbari were written by Abul Fazl, not his brother Faizi; Alamgir was Aurangzeb's title; and the Red Fort of Delhi was built by Shah Jahan.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. जहाँगीर के संस्मरण का नाम तुजुक-ए-जहाँगीरी है। II. आइन-ए-अकबरी फैजी के अकबरनामा का तीसरा खंड है। III. शाहजहाँ ने आलमगीर की उपाधि धारण की। IV. दिल्ली का लाल किला अकबर ने बनवाया था।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है। अकबरनामा और आइन-ए-अकबरी अबुल फजल ने लिखे थे, उसके भाई फैजी ने नहीं; आलमगीर औरंगजेब की उपाधि थी; और दिल्ली का लाल किला शाहजहाँ ने बनवाया था।"},
  {"id":"history-mughal-29","question":"Humayun’s Tomb, the first great garden-tomb of the Mughals and a model for the Taj Mahal, stands in:","options":["Agra","Delhi","Lahore","Fatehpur Sikri"],"answer":1,"explanation":"The tomb in Delhi was commissioned by Humayun’s widow Bega Begum (Haji Begum) and completed around 1572; it is a UNESCO World Heritage Site.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"हुमायूँ का मकबरा, जो मुगलों का पहला महान उद्यान-मकबरा और ताजमहल का प्रेरणा-स्रोत है, कहाँ स्थित है?","optionsHi":["आगरा","दिल्ली","लाहौर","फतेहपुर सीकरी"],"explanationHi":"दिल्ली स्थित यह मकबरा हुमायूँ की विधवा बेगा बेगम (हाजी बेगम) ने बनवाना शुरू किया और लगभग 1572 में पूरा हुआ; यह यूनेस्को विश्व धरोहर स्थल है।"},
  {"id":"history-mughal-30","question":"The original name of Jahangir’s empress Nur Jahan was:","options":["Mehr-un-Nisa","Mumtaz Mahal","Jahanara","Arjumand Banu Begum"],"answer":0,"explanation":"Mehr-un-Nisa, daughter of Mirza Ghiyas Beg (Itimad-ud-Daulah), married Jahangir in 1611 and was titled Nur Mahal and then Nur Jahan. Arjumand Banu was Mumtaz Mahal, her niece.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"जहाँगीर की बेगम नूरजहाँ का मूल नाम क्या था?","optionsHi":["मेहरुन्निसा","मुमताज महल","जहाँआरा","अर्जुमंद बानो बेगम"],"explanationHi":"मिर्जा गियास बेग (इतिमादुद्दौला) की पुत्री मेहरुन्निसा ने 1611 में जहाँगीर से विवाह किया और उन्हें नूर महल, फिर नूरजहाँ की उपाधि मिली। अर्जुमंद बानो मुमताज महल थी, जो उनकी भतीजी थी।"},
  {"id":"history-mughal-31","question":"Which Mughal emperor was called “Zinda Pir” (living saint) because of his austere, orthodox life?","options":["Akbar","Shah Jahan","Aurangzeb","Bahadur Shah I"],"answer":2,"explanation":"Aurangzeb copied the Quran, stitched caps for a living and banned court music, earning the epithet Zinda Pir from his orthodox admirers.","difficulty":"easy","source":"SSC CGL · UPSSSC PET","questionHi":"अपने तपस्वी, रूढ़िवादी जीवन के कारण किस मुगल सम्राट को “जिंदा पीर” (जीवित संत) कहा जाता था?","optionsHi":["अकबर","शाहजहाँ","औरंगजेब","बहादुर शाह प्रथम"],"explanationHi":"औरंगजेब कुरान की प्रतियाँ लिखता था, टोपियाँ सिलकर अपना निर्वाह करता था और उसने दरबार में संगीत पर प्रतिबंध लगाया, जिससे उसके रूढ़िवादी प्रशंसकों ने उसे जिंदा पीर की उपाधि दी।"},
  {"id":"history-mughal-32","question":"Who among the following was NOT one of the Navratnas (nine jewels) of Akbar’s court?","options":["Raja Todar Mal","Abdur Rahim Khan-i-Khanan","Bairam Khan","Mullah Do-Piyaza"],"answer":2,"explanation":"Bairam Khan was Akbar’s regent, dismissed in 1560 and killed on his way to Mecca, long before the Navratnas gathered. The nine were Abul Fazl, Faizi, Tansen, Birbal, Todar Mal, Man Singh, Abdur Rahim, Fakir Aziao-Din and Mullah Do-Piyaza.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"निम्नलिखित में से कौन अकबर के दरबार के नवरत्नों (नौ रत्नों) में से एक नहीं था?","optionsHi":["राजा टोडरमल","अब्दुर्रहीम खान-ए-खानाँ","बैरम खाँ","मुल्ला दो-प्याजा"],"explanationHi":"बैरम खाँ अकबर का संरक्षक था, जिसे 1560 में हटा दिया गया और जो मक्का जाते समय मारा गया, नवरत्नों के एकत्र होने से बहुत पहले। नौ रत्न थे: अबुल फजल, फैजी, तानसेन, बीरबल, टोडरमल, मान सिंह, अब्दुर्रहीम, फकीर अजियाउद्दीन और मुल्ला दो-प्याजा।"},
  {"id":"history-mughal-33","question":"The Battle of Ghaghra (1529), the last major battle of Babur in India, was fought against:","options":["Rana Sanga and his Rajputs","Afghans under Mahmud Lodi","Medini Rai of Chanderi","Sher Khan Sur of Sasaram"],"answer":1,"explanation":"Babur defeated the Afghan chiefs of Bihar and Bengal under Mahmud Lodi (brother of Ibrahim Lodi) on the Ghaghra. Rana Sanga was beaten at Khanwa (1527) and Medini Rai at Chanderi (1528).","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"घाघरा का युद्ध (1529), जो भारत में बाबर का अंतिम प्रमुख युद्ध था, किसके विरुद्ध लड़ा गया?","optionsHi":["राणा सांगा और उसके राजपूत","महमूद लोदी के नेतृत्व में अफगान","चंदेरी का मेदिनी राय","ससाराम का शेर खाँ सूर"],"explanationHi":"बाबर ने घाघरा नदी पर महमूद लोदी (इब्राहिम लोदी का भाई) के नेतृत्व में बिहार और बंगाल के अफगान सरदारों को हराया। राणा सांगा खानवा (1527) में और मेदिनी राय चंदेरी (1528) में पराजित हुए थे।"},
  {"id":"history-mughal-34","question":"The “Chain of Justice” (zanjir-i-adl), a golden chain with bells that any petitioner could pull, was set up by:","options":["Akbar","Jahangir","Shah Jahan","Sher Shah"],"answer":1,"explanation":"Jahangir hung the chain between the Shah Burj of Agra fort and a post on the river bank so that aggrieved subjects could reach the emperor directly; it is described in his memoir.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"“न्याय की जंजीर” (जंजीर-ए-अदल), घंटियों वाली एक सोने की जंजीर जिसे कोई भी फरियादी खींच सकता था, किसने लगवाई थी?","optionsHi":["अकबर","जहाँगीर","शाहजहाँ","शेरशाह"],"explanationHi":"जहाँगीर ने आगरा किले के शाह बुर्ज और नदी तट के एक खंभे के बीच यह जंजीर लटकवाई, ताकि पीड़ित प्रजा सीधे सम्राट तक पहुँच सके; इसका वर्णन उसके संस्मरण में मिलता है।"},
  {"id":"history-mughal-35","question":"After the war of succession, Shah Jahan was imprisoned by Aurangzeb for the last eight years of his life in:","options":["Red Fort, Delhi","Agra Fort","Gwalior Fort","Lahore Fort"],"answer":1,"explanation":"Shah Jahan was confined in Agra Fort from 1658 until his death in 1666, cared for by his daughter Jahanara, within sight of the Taj Mahal.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"उत्तराधिकार के युद्ध के बाद शाहजहाँ को औरंगजेब ने अपने जीवन के अंतिम आठ वर्ष कहाँ कैद रखा?","optionsHi":["लाल किला, दिल्ली","आगरा किला","ग्वालियर किला","लाहौर किला"],"explanationHi":"शाहजहाँ 1658 से 1666 में अपनी मृत्यु तक आगरा किले में कैद रहा; ताजमहल की दृष्टि सीमा में उसकी पुत्री जहाँआरा उसकी देखभाल करती रही।"},
  {"id":"history-mughal-36","question":"Sir Thomas Roe, ambassador of King James I of England, visited the court of:","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb"],"answer":1,"explanation":"Roe stayed at Jahangir’s court from 1615 to 1619 and obtained trading concessions for the East India Company; William Hawkins had visited earlier (1608–11).","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"इंग्लैंड के राजा जेम्स प्रथम के राजदूत सर थॉमस रो किसके दरबार में आए थे?","optionsHi":["अकबर","जहाँगीर","शाहजहाँ","औरंगजेब"],"explanationHi":"रो 1615 से 1619 तक जहाँगीर के दरबार में रहा और उसने ईस्ट इंडिया कंपनी के लिए व्यापारिक रियायतें प्राप्त कीं; विलियम हॉकिन्स इससे पहले (1608–11) आया था।"},
  {"id":"history-mughal-37","question":"In the Battle of Chanderi (1528), Babur defeated the Rajput chief:","options":["Rana Sanga","Medini Rai","Hasan Khan Mewati","Rana Udai Singh"],"answer":1,"explanation":"Medini Rai, an ally of Rana Sanga, held Chanderi in Malwa; its capture in January 1528 secured Babur’s hold over central India. Hasan Khan Mewati fought at Khanwa.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"चंदेरी के युद्ध (1528) में बाबर ने किस राजपूत सरदार को पराजित किया?","optionsHi":["राणा सांगा","मेदिनी राय","हसन खाँ मेवाती","राणा उदय सिंह"],"explanationHi":"राणा सांगा का सहयोगी मेदिनी राय मालवा के चंदेरी पर अधिकार रखता था; जनवरी 1528 में उसके पतन से मध्य भारत पर बाबर की पकड़ मजबूत हुई। हसन खाँ मेवाती खानवा में लड़ा था।"},
  {"id":"history-mughal-38","question":"Humayun recovered Delhi in 1555 after his forces defeated which Sur ruler at the Battle of Sirhind?","options":["Islam Shah Sur","Sikandar Shah Sur","Muhammad Adil Shah Sur","Sher Shah Sur"],"answer":1,"explanation":"Bairam Khan led Humayun’s army to victory over Sikandar Shah Sur at Sirhind in June 1555, ending the Sur interregnum; Humayun died in January 1556 after a fall from his library stairs.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"सरहिंद के युद्ध में हुमायूँ की सेना ने किस सूर शासक को पराजित करके 1555 में दिल्ली पुनः प्राप्त की?","optionsHi":["इस्लाम शाह सूर","सिकंदर शाह सूर","मुहम्मद आदिल शाह सूर","शेरशाह सूर"],"explanationHi":"बैरम खाँ के नेतृत्व में हुमायूँ की सेना ने जून 1555 में सरहिंद में सिकंदर शाह सूर पर विजय पाई, जिससे सूर वंश का अंतराल समाप्त हुआ; हुमायूँ की मृत्यु जनवरी 1556 में अपने पुस्तकालय की सीढ़ियों से गिरने के कारण हुई।"},
  {"id":"history-mughal-39","question":"Akbar’s first matrimonial alliance with a Rajput house (1562) was with the daughter of Raja Bharmal of:","options":["Marwar","Mewar","Amber","Bikaner"],"answer":2,"explanation":"Harkha Bai (popularly Jodha Bai), daughter of Bharmal of Amber (Jaipur), married Akbar in 1562 and became the mother of Jahangir; Mewar under Rana Pratap never submitted.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"अकबर का किसी राजपूत घराने से पहला वैवाहिक संबंध (1562) किस राज्य के राजा भारमल की पुत्री से हुआ?","optionsHi":["मारवाड़ के","मेवाड़ के","आमेर के","बीकानेर के"],"explanationHi":"आमेर (जयपुर) के भारमल की पुत्री हरखा बाई (प्रचलित नाम जोधा बाई) ने 1562 में अकबर से विवाह किया और जहाँगीर की माता बनीं; राणा प्रताप के अधीन मेवाड़ ने कभी अधीनता स्वीकार नहीं की।"},
  {"id":"history-mughal-40","question":"Aurangzeb annexed the Deccan sultanates of Bijapur and Golconda respectively in:","options":["1636 and 1656","1686 and 1687","1681 and 1689","1676 and 1686"],"answer":1,"explanation":"Bijapur fell in 1686 and Golconda in 1687, after which Aurangzeb spent the rest of his reign fighting the Marathas in the Deccan.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"औरंगजेब ने दक्कन की सल्तनतों बीजापुर और गोलकुंडा को क्रमशः किस वर्ष मिलाया?","optionsHi":["1636 और 1656","1686 और 1687","1681 और 1689","1676 और 1686"],"explanationHi":"बीजापुर 1686 में और गोलकुंडा 1687 में गिरा, जिसके बाद औरंगजेब ने अपना शेष शासनकाल दक्कन में मराठों से लड़ते हुए बिताया।"},
  {"id":"history-mughal-41","question":"Which Mughal emperor drove the Portuguese out of their settlement at Hugli in Bengal in 1632?","options":["Jahangir","Shah Jahan","Aurangzeb","Akbar the Great"],"answer":1,"explanation":"Shah Jahan ordered the siege of Hugli because of Portuguese piracy and slave-trading; the settlement was sacked and many Portuguese taken prisoner.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"किस मुगल सम्राट ने 1632 में बंगाल के हुगली में पुर्तगालियों की बस्ती से उन्हें खदेड़ दिया?","optionsHi":["जहाँगीर","शाहजहाँ","औरंगजेब","महान अकबर"],"explanationHi":"शाहजहाँ ने पुर्तगालियों की समुद्री लूटपाट और दास-व्यापार के कारण हुगली की घेराबंदी का आदेश दिया; बस्ती लूट ली गई और अनेक पुर्तगाली बंदी बनाए गए।"},
  {"id":"history-mughal-42","question":"Guru Arjan Dev, the fifth Sikh Guru, was executed in 1606 during the reign of:","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb"],"answer":1,"explanation":"Jahangir had Guru Arjan executed for allegedly helping the rebel prince Khusrau. Guru Tegh Bahadur was executed in 1675 under Aurangzeb.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"पाँचवें सिख गुरु, गुरु अर्जन देव को 1606 में किसके शासनकाल में मृत्युदंड दिया गया?","optionsHi":["अकबर","जहाँगीर","शाहजहाँ","औरंगजेब"],"explanationHi":"जहाँगीर ने विद्रोही शहजादे खुसरो की कथित सहायता के आरोप में गुरु अर्जन को मृत्युदंड दिया। गुरु तेग बहादुर को 1675 में औरंगजेब के अधीन मृत्युदंड दिया गया था।"},
  {"id":"history-mughal-43","question":"The “Padshahnama”, the official history of Shah Jahan’s reign, was written by:","options":["Abdul Hamid Lahori","Abul Fazl Allami","Muhammad Hashim Khafi Khan","Mutamid Khan"],"answer":0,"explanation":"Abdul Hamid Lahori wrote the Padshahnama; Khafi Khan wrote the Muntakhab-ul-Lubab on Aurangzeb’s reign and Mutamid Khan the Iqbalnama-i-Jahangiri.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"शाहजहाँ के शासनकाल का आधिकारिक इतिहास “पादशाहनामा” किसने लिखा था?","optionsHi":["अब्दुल हमीद लाहौरी","अबुल फजल अल्लामी","मुहम्मद हाशिम खफी खाँ","मुतमिद खाँ"],"explanationHi":"पादशाहनामा अब्दुल हमीद लाहौरी ने लिखा; खफी खाँ ने औरंगजेब के काल पर मुंतखब-उल-लुबाब और मुतमिद खाँ ने इकबालनामा-ए-जहाँगीरी लिखा।"},
  {"id":"history-mughal-44","question":"Akbar’s Dahsala system, which fixed revenue on the basis of the average produce and prices of the previous ten years, was introduced in:","options":["1560","1571","1580","1596"],"answer":2,"explanation":"Todar Mal introduced the Dahsala (Ain-i-Dahsala) in 1580, the 24th year of Akbar’s reign, after the earlier experiments with karori officers (1574).","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अकबर की दहसाला प्रणाली, जिसमें पिछले दस वर्षों की औसत उपज और कीमतों के आधार पर राजस्व निर्धारित किया जाता था, कब शुरू की गई?","optionsHi":["1560","1571","1580","1596"],"explanationHi":"टोडरमल ने अकबर के शासन के 24वें वर्ष, 1580 में दहसाला (आइन-ए-दहसाला) शुरू की, इससे पहले करोड़ी अधिकारियों के साथ प्रयोग (1574) किए गए थे।"},
  {"id":"history-mughal-45","question":"At the First Battle of Panipat, Babur’s artillery was commanded by:","options":["Ustad Ali Quli and Mustafa Rumi","Bairam Khan and Tardi Beg Khan","Princes Humayun and Kamran Mirza","Mir Baqi and Zahid Beg"],"answer":0,"explanation":"The Ottoman-trained gunners Ustad Ali Quli and Mustafa Rumi managed Babur’s cannon, used with the Tulughma flanking tactic and the Rumi (Ottoman) device of chained carts.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"पानीपत के प्रथम युद्ध में बाबर के तोपखाने का संचालन किसने किया?","optionsHi":["उस्ताद अली कुली और मुस्तफा रूमी","बैरम खाँ और तर्दी बेग खाँ","शहजादे हुमायूँ और कामरान मिर्जा","मीर बाकी और जाहिद बेग"],"explanationHi":"उस्मानी प्रशिक्षण प्राप्त तोपचियों उस्ताद अली कुली और मुस्तफा रूमी ने बाबर की तोपों का संचालन किया, जिन्हें तुलुगमा पार्श्व-आक्रमण रणनीति और रूमी (उस्मानी) युक्ति, यानी जंजीरों से बँधी गाड़ियों, के साथ प्रयोग किया गया।"},
  {"id":"history-mughal-46","question":"The “Fatawa-i-Alamgiri”, a digest of Islamic law, was compiled under the orders of:","options":["Akbar","Shah Jahan","Aurangzeb","Jahangir"],"answer":2,"explanation":"Aurangzeb (Alamgir) had a body of scholars compile the Fatawa-i-Alamgiri as the authoritative code of Hanafi law for his empire.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"इस्लामी कानून के संकलन “फतवा-ए-आलमगीरी” का संकलन किसके आदेश से हुआ?","optionsHi":["अकबर","शाहजहाँ","औरंगजेब","जहाँगीर"],"explanationHi":"औरंगजेब (आलमगीर) ने विद्वानों के एक दल से फतवा-ए-आलमगीरी का संकलन करवाया, जो उसके साम्राज्य के लिए हनफी कानून की प्रामाणिक संहिता थी।"},
  {"id":"history-mughal-47","question":"Arrange in chronological order: 1. Battle of Sirhind 2. Battle of Ghaghra 3. Battle of Kannauj (Bilgram) 4. Battle of Samugarh","options":["2, 3, 1, 4","2, 1, 3, 4","3, 2, 1, 4","2, 3, 4, 1"],"answer":0,"explanation":"Ghaghra (1529), Kannauj (1540, Sher Shah defeats Humayun), Sirhind (1555, Humayun returns) and Samugarh (1658, Aurangzeb defeats Dara Shikoh).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. सरहिंद का युद्ध 2. घाघरा का युद्ध 3. कन्नौज (बिलग्राम) का युद्ध 4. सामूगढ़ का युद्ध","optionsHi":["2, 3, 1, 4","2, 1, 3, 4","3, 2, 1, 4","2, 3, 4, 1"],"explanationHi":"घाघरा (1529), कन्नौज (1540, शेरशाह ने हुमायूँ को हराया), सरहिंद (1555, हुमायूँ की वापसी) और सामूगढ़ (1658, औरंगजेब ने दारा शिकोह को हराया)।"},
  {"id":"history-mughal-48","question":"How many of these statements about Akbar are correct? I. He was born at Amarkot in 1542. II. He was crowned at Kalanaur in 1556. III. He captured Chittor in 1568 and Ranthambore in 1569. IV. He built the Buland Darwaza at Fatehpur Sikri.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Akbar was born at Amarkot in 1542, crowned at Kalanaur in 1556, took Chittor (1568) and Ranthambore (1569), and built the Buland Darwaza to mark his Gujarat victory.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अकबर के बारे में इनमें से कितने कथन सही हैं? I. उसका जन्म 1542 में अमरकोट में हुआ। II. 1556 में कलानौर में उसका राज्याभिषेक हुआ। III. उसने 1568 में चित्तौड़ और 1569 में रणथंभौर जीता। IV. उसने फतेहपुर सीकरी में बुलंद दरवाजा बनवाया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। अकबर का जन्म 1542 में अमरकोट में हुआ, राज्याभिषेक 1556 में कलानौर में हुआ, उसने चित्तौड़ (1568) और रणथंभौर (1569) जीते, और गुजरात विजय की स्मृति में बुलंद दरवाजा बनवाया।"},
  {"id":"history-mughal-49","question":"Which pair of Mughal-period work and its author is NOT correctly matched?","options":["Akbarnama – Abul Fazl","Tabaqat-i-Akbari – Nizamuddin Ahmad","Muntakhab-ut-Tawarikh – Abdul Qadir Badauni","Humayun-nama – Abul Fazl"],"answer":3,"explanation":"The Humayun-nama was written by Gulbadan Begum, Babur’s daughter and Humayun’s sister, at Akbar’s request.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"मुगलकालीन रचना और उसके लेखक की कौन-सी जोड़ी सही सुमेलित नहीं है?","optionsHi":["अकबरनामा – अबुल फजल","तबकात-ए-अकबरी – निजामुद्दीन अहमद","मुंतखब-उत-तवारीख – अब्दुल कादिर बदायूँनी","हुमायूँनामा – अबुल फजल"],"explanationHi":"हुमायूँनामा गुलबदन बेगम ने लिखा था, जो बाबर की पुत्री और हुमायूँ की बहन थीं; उन्होंने यह अकबर के अनुरोध पर लिखा।"},
  {"id":"history-mughal-50","question":"Assertion (A): Mughal painting reached its peak in the reign of Jahangir. Reason (R): Jahangir was a connoisseur who patronised masters like Mansur and Abul Hasan and claimed he could identify the hand of each artist in a composite picture.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Jahangir’s personal patronage and his taste for portraiture and natural-history painting (Mansur’s birds and animals) explain why his reign is seen as the climax of Mughal painting.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): मुगल चित्रकला जहाँगीर के शासनकाल में अपने शिखर पर पहुँची। कारण (R): जहाँगीर एक पारखी था जिसने मंसूर और अबुल हसन जैसे उस्तादों को संरक्षण दिया और दावा करता था कि वह मिश्रित चित्र में प्रत्येक कलाकार का हाथ पहचान सकता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, किंतु R, A की सही व्याख्या नहीं है","A सत्य है, किंतु R असत्य है","A असत्य है, किंतु R सत्य है"],"explanationHi":"जहाँगीर का व्यक्तिगत संरक्षण तथा व्यक्ति-चित्रण और प्राकृतिक इतिहास की चित्रकला (मंसूर के पक्षी और पशु) के प्रति उसकी रुचि यह स्पष्ट करती है कि उसके शासनकाल को मुगल चित्रकला का चरमोत्कर्ष क्यों माना जाता है।"},
  {"id":"history-mughal-51","question":"How many of these statements about Aurangzeb are correct? I. He banned music at the court. II. He had the Maratha king Sambhaji executed in 1689. III. He died at Aurangabad in 1707. IV. The Peacock Throne was carried away from Delhi during his reign.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. Aurangzeb died at Ahmednagar in 1707 (he is buried at Khuldabad near Aurangabad), and Nadir Shah carried off the Peacock Throne in 1739, in the reign of Muhammad Shah.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"औरंगजेब के बारे में इनमें से कितने कथन सही हैं? I. उसने दरबार में संगीत पर प्रतिबंध लगाया। II. उसने 1689 में मराठा राजा संभाजी को मृत्युदंड दिया। III. उसकी मृत्यु 1707 में औरंगाबाद में हुई। IV. उसके शासनकाल में मयूर सिंहासन दिल्ली से ले जाया गया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। औरंगजेब की मृत्यु 1707 में अहमदनगर में हुई (उसे औरंगाबाद के निकट खुल्दाबाद में दफनाया गया), और नादिर शाह मयूर सिंहासन को 1739 में, मुहम्मद शाह के शासनकाल में, ले गया।"},
  {"id":"history-mughal-52","question":"How many of these statements about the mansabdari system are correct? I. The zat rank fixed the personal status and salary of the mansabdar. II. Mansabdars were paid either in cash or through a jagir. III. The du-aspah sih-aspah rank was introduced by Jahangir. IV. The dagh (branding of horses) system was enforced by Akbar.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Du-aspah sih-aspah let a mansabdar maintain double the number of troopers for the same sawar rank; dagh prevented fraud in the muster of horses.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मनसबदारी प्रणाली के बारे में इनमें से कितने कथन सही हैं? I. जात पद मनसबदार की व्यक्तिगत प्रतिष्ठा और वेतन निर्धारित करता था। II. मनसबदारों को नकद या जागीर के रूप में वेतन दिया जाता था। III. दो-अस्पा सिह-अस्पा पद जहाँगीर ने शुरू किया। IV. दाग (घोड़ों को दागने) की प्रथा अकबर ने लागू की।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। दो-अस्पा सिह-अस्पा के अंतर्गत मनसबदार उसी सवार पद के लिए दुगुने घुड़सवार रख सकता था; दाग प्रथा घोड़ों की गिनती में धोखाधड़ी को रोकती थी।"},
  {"id":"history-mughal-53","question":"Arrange in chronological order: 1. Third Battle of Panipat 2. Battle of Buxar 3. Nadir Shah’s sack of Delhi 4. Death of Aurangzeb","options":["4, 3, 1, 2","4, 1, 3, 2","3, 4, 1, 2","4, 3, 2, 1"],"answer":0,"explanation":"Aurangzeb’s death (1707), Nadir Shah’s invasion (1739), Third Battle of Panipat (1761) and Buxar (1764).","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. पानीपत का तृतीय युद्ध 2. बक्सर का युद्ध 3. नादिर शाह द्वारा दिल्ली की लूट 4. औरंगजेब की मृत्यु","optionsHi":["4, 3, 1, 2","4, 1, 3, 2","3, 4, 1, 2","4, 3, 2, 1"],"explanationHi":"औरंगजेब की मृत्यु (1707), नादिर शाह का आक्रमण (1739), पानीपत का तृतीय युद्ध (1761) और बक्सर (1764)।"},
  {"id":"history-mughal-54","question":"Which pair of Mughal monument and its builder is NOT correctly matched?","options":["Buland Darwaza – Akbar","Tomb of Itimad-ud-Daulah – Nur Jahan","Bibi ka Maqbara – Azam Shah, son of Aurangzeb","Jama Masjid, Delhi – Aurangzeb"],"answer":3,"explanation":"The Jama Masjid of Delhi (1656) was built by Shah Jahan. Bibi ka Maqbara at Aurangabad, a copy of the Taj, was built by Azam Shah for his mother.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"मुगल स्मारक और उसके निर्माता की कौन-सी जोड़ी सही सुमेलित नहीं है?","optionsHi":["बुलंद दरवाजा – अकबर","इतिमादुद्दौला का मकबरा – नूरजहाँ","बीबी का मकबरा – आजम शाह, औरंगजेब का पुत्र","जामा मस्जिद, दिल्ली – औरंगजेब"],"explanationHi":"दिल्ली की जामा मस्जिद (1656) शाहजहाँ ने बनवाई थी। औरंगाबाद का बीबी का मकबरा, जो ताजमहल की अनुकृति है, आजम शाह ने अपनी माता के लिए बनवाया था।"},
  {"id":"history-mughal-55","question":"How many of these statements about Sher Shah Suri are correct? I. His original name was Farid Khan. II. He built the Qila-i-Kuhna mosque inside the Purana Qila at Delhi. III. He died in 1545 during the siege of Kalinjar. IV. He introduced the patta and qabuliyat documents in land revenue.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Sher Shah was killed by a gunpowder explosion at Kalinjar; his revenue practices were later adopted by Akbar.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"शेरशाह सूरी के बारे में इनमें से कितने कथन सही हैं? I. उसका मूल नाम फरीद खाँ था। II. उसने दिल्ली के पुराने किले के भीतर किला-ए-कुहना मस्जिद बनवाई। III. उसकी मृत्यु 1545 में कालिंजर की घेराबंदी के दौरान हुई। IV. उसने भू-राजस्व में पट्टा और कबूलियत के दस्तावेज शुरू किए।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। शेरशाह कालिंजर में बारूद के विस्फोट से मारा गया; उसकी राजस्व पद्धतियों को बाद में अकबर ने अपनाया।"},
  {"id":"history-mughal-56","question":"Assertion (A): Babur’s victory at Panipat in 1526 did not immediately make him the master of Hindustan. Reason (R): The Rajput confederacy under Rana Sanga and the Afghan chiefs in the east still challenged him, forcing the battles of Khanwa and Ghaghra.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Panipat only removed Ibrahim Lodi; Khanwa (1527) broke Rajput power and Ghaghra (1529) the Afghan resistance, securing Babur’s rule.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): 1526 में पानीपत की विजय से बाबर तुरंत हिंदुस्तान का स्वामी नहीं बन गया। कारण (R): राणा सांगा के नेतृत्व वाला राजपूत संघ और पूर्व के अफगान सरदार अब भी उसे चुनौती दे रहे थे, जिससे खानवा और घाघरा के युद्ध हुए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, किंतु R, A की सही व्याख्या नहीं है","A सत्य है, किंतु R असत्य है","A असत्य है, किंतु R सत्य है"],"explanationHi":"पानीपत ने केवल इब्राहिम लोदी को हटाया; खानवा (1527) ने राजपूत शक्ति को और घाघरा (1529) ने अफगान प्रतिरोध को तोड़ा, जिससे बाबर का शासन सुरक्षित हुआ।"},
  {"id":"history-mughal-57","question":"How many of these statements about the later Mughals are correct? I. Bahadur Shah I succeeded Aurangzeb. II. Farrukhsiyar issued the farman of 1717 granting trade privileges to the East India Company in Bengal. III. Muhammad Shah “Rangeela” was the emperor when Nadir Shah invaded India. IV. Bahadur Shah Zafar was exiled to Rangoon after the revolt of 1857.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The 1717 farman has been called the Magna Carta of the Company; Bahadur Shah Zafar died in Rangoon in 1862.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"परवर्ती मुगलों के बारे में इनमें से कितने कथन सही हैं? I. बहादुर शाह प्रथम औरंगजेब का उत्तराधिकारी बना। II. फर्रुखसियर ने 1717 का वह फरमान जारी किया जिसने ईस्ट इंडिया कंपनी को बंगाल में व्यापारिक विशेषाधिकार दिए। III. जब नादिर शाह ने भारत पर आक्रमण किया तब मुहम्मद शाह “रंगीला” सम्राट था। IV. 1857 के विद्रोह के बाद बहादुर शाह जफर को रंगून निर्वासित किया गया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। 1717 के फरमान को कंपनी का “मैग्ना कार्टा” कहा गया है; बहादुर शाह जफर की मृत्यु 1862 में रंगून में हुई।"},
  {"id":"history-mughal-58","question":"Which pair of 18th-century noble and the state he founded is NOT correctly matched?","options":["Chin Qilich Khan (Nizam-ul-Mulk) – Hyderabad","Saadat Khan – Awadh","Murshid Quli Khan – Awadh","Sayyid brothers – known as king-makers at Delhi"],"answer":2,"explanation":"Murshid Quli Khan made Bengal virtually independent (capital Murshidabad); Awadh was founded by Saadat Khan Burhan-ul-Mulk in 1722 and Hyderabad by Nizam-ul-Mulk in 1724.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"18वीं सदी के सरदार और उसके द्वारा स्थापित राज्य की कौन-सी जोड़ी सही सुमेलित नहीं है?","optionsHi":["चिन किलिच खाँ (निजाम-उल-मुल्क) – हैदराबाद","सआदत खाँ – अवध","मुर्शिद कुली खाँ – अवध","सैयद बंधु – दिल्ली में किंगमेकर (बादशाह बनाने वाले) के रूप में प्रसिद्ध"],"explanationHi":"मुर्शिद कुली खाँ ने बंगाल को लगभग स्वतंत्र कर दिया था (राजधानी मुर्शिदाबाद); अवध की स्थापना सआदत खाँ बुरहान-उल-मुल्क ने 1722 में और हैदराबाद की निजाम-उल-मुल्क ने 1724 में की थी।"},
  {"id":"history-mughal-59","question":"The tomb of Akbar is located at:","options":["Fatehpur Sikri, near Agra","Sikandra, near Agra","Shahdara, Lahore","Nizamuddin, Delhi"],"answer":1,"explanation":"Akbar’s tomb is at Sikandra near Agra; Akbar began it and Jahangir completed it. Jahangir’s own tomb is at Shahdara, Lahore.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"अकबर का मकबरा कहाँ स्थित है?","optionsHi":["फतेहपुर सीकरी, आगरा के निकट","सिकंदरा, आगरा के निकट","शाहदरा, लाहौर","निजामुद्दीन, दिल्ली"],"explanationHi":"अकबर का मकबरा आगरा के निकट सिकंदरा में है; अकबर ने इसे शुरू किया और जहाँगीर ने पूरा किया। जहाँगीर का अपना मकबरा लाहौर के शाहदरा में है।"},
  {"id":"history-mughal-60","question":"Which Mughal emperor died in 1556 after falling down the stairs of his library, the Sher Mandal, in Delhi?","options":["Babur","Akbar","Humayun","Jahangir"],"answer":2,"explanation":"Humayun fell from the steps of the Sher Mandal in the Purana Qila a few months after regaining Delhi, and 13-year-old Akbar succeeded him.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"किस मुगल सम्राट की 1556 में दिल्ली में अपने पुस्तकालय शेर मंडल की सीढ़ियों से गिरकर मृत्यु हुई?","optionsHi":["बाबर","अकबर","हुमायूँ","जहाँगीर"],"explanationHi":"दिल्ली पुनः प्राप्त करने के कुछ महीने बाद हुमायूँ पुराने किले में शेर मंडल की सीढ़ियों से गिर गया, और 13 वर्षीय अकबर उसका उत्तराधिकारी बना।"},
  {"id":"history-mughal-61","question":"Babur was descended from:","options":["Timur on his father’s side and Genghis Khan on his mother’s side","Genghis Khan on his father’s side and Timur on his mother’s side","The Lodi Afghans","The Safavid rulers of Persia"],"answer":0,"explanation":"Babur was a Timurid through his father, Umar Shaikh Mirza, and descended from Genghis Khan through his mother, a Chagatai princess.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"बाबर किसका वंशज था?","optionsHi":["पिता की ओर से तैमूर का और माता की ओर से चंगेज खाँ का","पिता की ओर से चंगेज खाँ का और माता की ओर से तैमूर का","लोदी अफगानों का","फारस के सफवी शासकों का"],"explanationHi":"बाबर अपने पिता उमर शेख मिर्जा के माध्यम से तैमूरी था और अपनी माता, एक चगताई राजकुमारी, के माध्यम से चंगेज खाँ का वंशज था।"},
  {"id":"history-mughal-62","question":"Before his accession, Jahangir was known as:","options":["Khurram","Murad","Daniyal","Salim"],"answer":3,"explanation":"Akbar named his son Salim after the Sufi saint Shaikh Salim Chishti of Sikri. Khurram was Shah Jahan’s name before accession.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"राज्यारोहण से पहले जहाँगीर किस नाम से जाना जाता था?","optionsHi":["खुर्रम","मुराद","दानियाल","सलीम"],"explanationHi":"अकबर ने अपने पुत्र का नाम सीकरी के सूफी संत शेख सलीम चिश्ती के नाम पर सलीम रखा। खुर्रम राज्यारोहण से पहले शाहजहाँ का नाम था।"},
  {"id":"history-mughal-63","question":"The Shalimar Bagh at Srinagar was laid out by:","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb"],"answer":1,"explanation":"Jahangir laid out the Shalimar Bagh in Srinagar for Nur Jahan. The Shalimar Bagh of Lahore was built later by Shah Jahan.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"श्रीनगर का शालीमार बाग किसने बनवाया था?","optionsHi":["अकबर","जहाँगीर","शाहजहाँ","औरंगजेब"],"explanationHi":"जहाँगीर ने नूरजहाँ के लिए श्रीनगर में शालीमार बाग बनवाया। लाहौर का शालीमार बाग बाद में शाहजहाँ ने बनवाया था।"},
  {"id":"history-mughal-64","question":"The tomb of Sher Shah Suri, set in the middle of an artificial lake, is at:","options":["Sasaram, Bihar","Purana Qila, Delhi","Narnaul, Haryana","Chunar, UP"],"answer":0,"explanation":"Sher Shah’s tomb at Sasaram, his family's jagir in Bihar, stands in an artificial lake and is a fine example of Indo-Afghan architecture. Narnaul has only the tomb of his grandfather Ibrahim Khan Sur.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"शेरशाह सूरी का मकबरा, जो एक कृत्रिम झील के बीच में है, कहाँ स्थित है?","optionsHi":["ससाराम, बिहार","पुराना किला, दिल्ली","नारनौल, हरियाणा","चुनार, उत्तर प्रदेश"],"explanationHi":"शेरशाह का मकबरा बिहार में उसके परिवार की जागीर ससाराम में, एक कृत्रिम झील में स्थित है और भारतीय-अफगान स्थापत्य का उत्कृष्ट उदाहरण है। नारनौल में केवल उसके दादा इब्राहिम खाँ सूर का मकबरा है।"},
  {"id":"history-mughal-65","question":"The Bibi Ka Maqbara at Aurangabad, modelled on the Taj Mahal, was built in memory of Aurangzeb’s wife Dilras Banu Begum by:","options":["Aurangzeb himself","Bahadur Shah I","Azam Shah","Kam Bakhsh"],"answer":2,"explanation":"Prince Azam Shah built it for his mother, Dilras Banu Begum, around 1660–61. It is often called the “Taj of the Deccan”.","difficulty":"moderate","source":"UPSC Prelims · State PSC","questionHi":"औरंगाबाद का बीबी का मकबरा, जो ताजमहल की अनुकृति है, औरंगजेब की पत्नी दिलरस बानो बेगम की स्मृति में किसने बनवाया?","optionsHi":["स्वयं औरंगजेब ने","बहादुर शाह प्रथम ने","आजम शाह ने","काम बख्श ने"],"explanationHi":"शहजादे आजम शाह ने इसे अपनी माता दिलरस बानो बेगम के लिए लगभग 1660–61 में बनवाया। इसे प्रायः “दक्कन का ताज” कहा जाता है।"},
  {"id":"history-mughal-66","question":"Akbar built the Ibadat Khana (House of Worship) at Fatehpur Sikri in:","options":["1562","1575","1582","1569"],"answer":1,"explanation":"The Ibadat Khana was built in 1575; at first only Muslim scholars debated there, but from 1578 it was opened to Hindus, Jains, Zoroastrians and Christians.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अकबर ने फतेहपुर सीकरी में इबादतखाना (उपासना गृह) कब बनवाया?","optionsHi":["1562","1575","1582","1569"],"explanationHi":"इबादतखाना 1575 में बना; आरंभ में वहाँ केवल मुस्लिम विद्वान बहस करते थे, परंतु 1578 से इसे हिंदुओं, जैनों, पारसियों और ईसाइयों के लिए खोल दिया गया।"},
  {"id":"history-mughal-67","question":"The “Muntakhab-ut-Tawarikh”, a history highly critical of Akbar’s religious policy, was written by:","options":["Abul Fazl","Khwaja Nizamuddin Ahmad","Faizi","Abdul Qadir Badauni"],"answer":3,"explanation":"Badauni, an orthodox scholar at Akbar’s court, wrote it privately. Abul Fazl wrote the official Akbarnama and Nizamuddin the Tabaqat-i-Akbari.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अकबर की धार्मिक नीति की कड़ी आलोचना करने वाला इतिहास “मुंतखब-उत-तवारीख” किसने लिखा?","optionsHi":["अबुल फजल","ख्वाजा निजामुद्दीन अहमद","फैजी","अब्दुल कादिर बदायूँनी"],"explanationHi":"अकबर के दरबार के रूढ़िवादी विद्वान बदायूँनी ने इसे निजी तौर पर लिखा। अबुल फजल ने आधिकारिक अकबरनामा और निजामुद्दीन ने तबकात-ए-अकबरी लिखा।"},
  {"id":"history-mughal-68","question":"Aurangzeb was buried in a simple open-air grave at:","options":["Ahmednagar","Mehrauli, Delhi","Khuldabad","Burhanpur"],"answer":2,"explanation":"Aurangzeb died at Ahmednagar in 1707 but was buried, as he wished, in an unadorned grave at Khuldabad near the shrine of Shaikh Zainuddin.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"औरंगजेब को कहाँ एक सादी खुली कब्र में दफनाया गया था?","optionsHi":["अहमदनगर","महरौली, दिल्ली","खुल्दाबाद","बुरहानपुर"],"explanationHi":"औरंगजेब की मृत्यु 1707 में अहमदनगर में हुई, पर अपनी इच्छा के अनुसार उसे शेख जैनुद्दीन की दरगाह के निकट खुल्दाबाद में बिना सजावट की कब्र में दफनाया गया।"},
  {"id":"history-mughal-69","question":"In 1580 Akbar divided his empire into how many subas (provinces)?","options":["8","12","15","21"],"answer":1,"explanation":"Akbar created 12 subas in 1580; the conquest of the Deccan raised the number to 15 by the end of his reign.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"1580 में अकबर ने अपने साम्राज्य को कितने सूबों (प्रांतों) में बाँटा?","optionsHi":["8","12","15","21"],"explanationHi":"अकबर ने 1580 में 12 सूबे बनाए; दक्कन की विजय से उसके शासन के अंत तक उनकी संख्या 15 हो गई।"},
  {"id":"history-mughal-70","question":"Guru Tegh Bahadur, the ninth Sikh Guru, was executed in Delhi in 1675 on the orders of:","options":["Jahangir","Shah Jahan","Bahadur Shah I","Aurangzeb"],"answer":3,"explanation":"Guru Tegh Bahadur was beheaded at Chandni Chowk (now Gurdwara Sis Ganj) in 1675 under Aurangzeb. Guru Arjan Dev was executed under Jahangir in 1606.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"नौवें सिख गुरु, गुरु तेग बहादुर को 1675 में दिल्ली में किसके आदेश पर मृत्युदंड दिया गया?","optionsHi":["जहाँगीर","शाहजहाँ","बहादुर शाह प्रथम","औरंगजेब"],"explanationHi":"गुरु तेग बहादुर का 1675 में औरंगजेब के शासनकाल में चाँदनी चौक (अब गुरुद्वारा शीश गंज) में सिर कलम किया गया। गुरु अर्जन देव को 1606 में जहाँगीर के अधीन मृत्युदंड दिया गया था।"},
  {"id":"history-mughal-71","question":"The standard copper coin of the Mughal currency system was the:","options":["Mohur","Dam","Rupiya","Tanka"],"answer":1,"explanation":"The Mughal system had the gold mohur, the silver rupiya and the copper dam; 40 dams made a rupee in Akbar’s time. The tanka belonged to the Delhi Sultanate.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"मुगल मुद्रा प्रणाली का मानक ताँबे का सिक्का कौन-सा था?","optionsHi":["मोहर","दाम","रुपिया","टंका"],"explanationHi":"मुगल प्रणाली में सोने की मोहर, चाँदी का रुपिया और ताँबे का दाम था; अकबर के समय 40 दाम का एक रुपया होता था। टंका दिल्ली सल्तनत का सिक्का था।"},
  {"id":"history-mughal-72","question":"The illustrated Hamzanama, one of the earliest major projects of Akbar’s painting workshop, was supervised by the Persian masters:","options":["Mansur and Abul Hasan","Farrukh Beg and Aqa Riza Herati","Mir Sayyid Ali, Abd al-Samad","Daswanth and Basawan"],"answer":2,"explanation":"Mir Sayyid Ali and Abd al-Samad, brought from Persia by Humayun, led the Hamzanama project. Farrukh Beg and Aqa Riza arrived later, Mansur and Abul Hasan flourished under Jahangir, and Daswanth and Basawan were Indian painters of Akbar's atelier.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"चित्रित हमजानामा, जो अकबर के चित्रशाला की प्रारंभिक प्रमुख परियोजनाओं में से एक था, का पर्यवेक्षण किन फारसी उस्तादों ने किया?","optionsHi":["मंसूर और अबुल हसन","फर्रुख बेग और आका रिजा हेरावी","मीर सैयद अली, अब्दुस समद","दसवंत और बसावन"],"explanationHi":"हुमायूँ द्वारा फारस से लाए गए मीर सैयद अली और अब्दुस समद ने हमजानामा परियोजना का नेतृत्व किया। फर्रुख बेग और आका रिजा बाद में आए, मंसूर और अबुल हसन जहाँगीर के काल में फले-फूले, और दसवंत तथा बसावन अकबर की चित्रशाला के भारतीय चित्रकार थे।"},
  {"id":"history-mughal-73","question":"Arrange these battles of the Mughal war of succession in chronological order: 1. Deorai 2. Samugarh 3. Dharmat 4. Khajwa","options":["3, 2, 1, 4","2, 3, 4, 1","3, 4, 2, 1","3, 2, 4, 1"],"answer":3,"explanation":"Dharmat (April 1658, over Jaswant Singh), Samugarh (May 1658, over Dara Shukoh), Khajwa (January 1659, over Shuja), Deorai (March 1659, Dara’s final defeat).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"मुगल उत्तराधिकार युद्ध की इन लड़ाइयों को कालक्रमानुसार व्यवस्थित कीजिए: 1. देवराई 2. सामूगढ़ 3. धरमत 4. खजवा","optionsHi":["3, 2, 1, 4","2, 3, 4, 1","3, 4, 2, 1","3, 2, 4, 1"],"explanationHi":"धरमत (अप्रैल 1658, जसवंत सिंह पर विजय), सामूगढ़ (मई 1658, दारा शिकोह पर विजय), खजवा (जनवरी 1659, शुजा पर विजय), देवराई (मार्च 1659, दारा की अंतिम पराजय)।"},
  {"id":"history-mughal-74","question":"Match the monument with its builder: A. Red sandstone Agra Fort B. Tomb of Itimad-ud-Daulah, Agra C. Badshahi Mosque, Lahore D. Jama Masjid, Delhi. 1. Shah Jahan 2. Aurangzeb 3. Nur Jahan 4. Akbar","options":["A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1","A-1, B-3, C-2, D-4","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Akbar rebuilt the Agra Fort in red sandstone; Nur Jahan built her father’s marble tomb with pietra dura; Aurangzeb built the Badshahi Mosque (1673); Shah Jahan built the Jama Masjid of Delhi.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"स्मारक का उसके निर्माता से मिलान कीजिए: A. लाल बलुआ पत्थर का आगरा किला B. इतिमादुद्दौला का मकबरा, आगरा C. बादशाही मस्जिद, लाहौर D. जामा मस्जिद, दिल्ली। 1. शाहजहाँ 2. औरंगजेब 3. नूरजहाँ 4. अकबर","optionsHi":["A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1","A-1, B-3, C-2, D-4","A-4, B-3, C-1, D-2"],"explanationHi":"अकबर ने आगरा किले को लाल बलुआ पत्थर से पुनः बनवाया; नूरजहाँ ने अपने पिता का संगमरमर का मकबरा पित्रा दुरा (जड़ाई कला) के साथ बनवाया; औरंगजेब ने बादशाही मस्जिद (1673) बनवाई; शाहजहाँ ने दिल्ली की जामा मस्जिद बनवाई।"},
  {"id":"history-mughal-75","question":"Assertion (A): Aurangzeb’s Deccan wars badly strained Mughal finances. Reason (R): Aurangzeb spent the last quarter-century of his reign, from 1681 to 1707, campaigning in the Deccan.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. The prolonged campaigns against Bijapur, Golconda and the Marathas drained the treasury and weakened control in the north.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): औरंगजेब के दक्कन युद्धों ने मुगल वित्त पर भारी बोझ डाला। कारण (R): औरंगजेब ने अपने शासन के अंतिम पच्चीस वर्ष, 1681 से 1707 तक, दक्कन में अभियानों में बिताए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, किंतु R, A की सही व्याख्या नहीं है","A सत्य है, किंतु R असत्य है","A असत्य है, किंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है। बीजापुर, गोलकुंडा और मराठों के विरुद्ध लंबे अभियानों ने खजाना खाली कर दिया और उत्तर में नियंत्रण कमजोर कर दिया।"},
  {"id":"history-mughal-76","question":"How many of these statements about Akbar’s religious policy are correct? I. His policy of Sulh-i-kul meant universal peace among faiths. II. The Ibadat Khana debates were thrown open to non-Muslims from 1578. III. Jesuit missions from Goa visited his court. IV. He issued the Mahzar in 1579.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Jesuit missions came from 1580 onward; the Mahzar (1579) made Akbar the arbiter in disputes over Islamic law.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अकबर की धार्मिक नीति के बारे में इनमें से कितने कथन सही हैं? I. उसकी सुलह-ए-कुल की नीति का अर्थ सभी धर्मों के बीच सार्वभौमिक शांति था। II. 1578 से इबादतखाना की बहसें गैर-मुस्लिमों के लिए खोल दी गईं। III. गोवा से जेसुइट मिशन उसके दरबार में आए। IV. उसने 1579 में महजर जारी किया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। जेसुइट मिशन 1580 से आए; महजर (1579) ने अकबर को इस्लामी कानून संबंधी विवादों में निर्णायक बना दिया।"},
  {"id":"history-mughal-77","question":"Match the Persian translation with the original work: A. Razmnama B. Translation by Badauni at Akbar’s order C. Sirr-i-Akbar D. Translation by Faizi. 1. Upanishads 2. Lilavati 3. Mahabharata 4. Ramayana","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1"],"answer":1,"explanation":"The Razmnama is the Persian Mahabharata; Badauni translated the Ramayana; Dara Shukoh’s Sirr-i-Akbar (1657) rendered fifty Upanishads; Faizi translated Bhaskara’s mathematical work Lilavati.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"फारसी अनुवाद का मूल ग्रंथ से मिलान कीजिए: A. रज्मनामा B. अकबर के आदेश पर बदायूँनी द्वारा अनुवाद C. सिर्र-ए-अकबर D. फैजी द्वारा अनुवाद। 1. उपनिषद 2. लीलावती 3. महाभारत 4. रामायण","optionsHi":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1"],"explanationHi":"रज्मनामा फारसी में महाभारत है; बदायूँनी ने रामायण का अनुवाद किया; दारा शिकोह के सिर्र-ए-अकबर (1657) ने पचास उपनिषदों का अनुवाद किया; फैजी ने भास्कर के गणितीय ग्रंथ लीलावती का अनुवाद किया।"},
  {"id":"history-mughal-78","question":"Arrange in chronological order: 1. William Hawkins at Jahangir’s court 2. Sir Thomas Roe at Jahangir’s court 3. Farrukhsiyar’s farman to the English 4. Shah Jahan expels the Portuguese from Hugli","options":["1, 2, 3, 4","2, 1, 4, 3","1, 4, 2, 3","1, 2, 4, 3"],"answer":3,"explanation":"Hawkins: 1609. Roe: 1615–19. Hugli captured from the Portuguese: 1632. Farrukhsiyar’s farman: 1717.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. जहाँगीर के दरबार में विलियम हॉकिन्स 2. जहाँगीर के दरबार में सर थॉमस रो 3. अंग्रेजों को फर्रुखसियर का फरमान 4. शाहजहाँ द्वारा पुर्तगालियों को हुगली से निकालना","optionsHi":["1, 2, 3, 4","2, 1, 4, 3","1, 4, 2, 3","1, 2, 4, 3"],"explanationHi":"हॉकिन्स: 1609। रो: 1615–19। पुर्तगालियों से हुगली छीनना: 1632। फर्रुखसियर का फरमान: 1717।"},
  {"id":"history-mughal-79","question":"How many of these statements about Babur are correct? I. He became ruler of Ferghana as a boy of about twelve. II. He used the tulughma tactic at the First Battle of Panipat. III. He took the title Padshah in 1507. IV. He was finally buried at Kabul.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Babur was first buried at Agra and later reburied in the Bagh-e Babur at Kabul, as he had wished.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"बाबर के बारे में इनमें से कितने कथन सही हैं? I. लगभग बारह वर्ष की आयु में वह फरगना का शासक बना। II. उसने पानीपत के प्रथम युद्ध में तुलुगमा रणनीति का प्रयोग किया। III. उसने 1507 में पादशाह की उपाधि धारण की। IV. उसे अंततः काबुल में दफनाया गया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। बाबर को पहले आगरा में दफनाया गया और बाद में उसकी इच्छा के अनुसार काबुल के बाग-ए-बाबर में पुनः दफनाया गया।"},
  {"id":"history-mughal-80","question":"Which of these was NOT built by Shah Jahan?","options":["Jama Masjid of Shahjahanabad","Moti Masjid in the Agra Fort","Shalimar Gardens at Lahore","Buland Darwaza at Sikri"],"answer":3,"explanation":"Akbar built the Buland Darwaza (c. 1575) to mark his Gujarat victory. Shah Jahan built the Jama Masjid, the Agra Fort Moti Masjid and the Shalimar gardens at Lahore.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"इनमें से किसका निर्माण शाहजहाँ ने नहीं करवाया?","optionsHi":["शाहजहानाबाद की जामा मस्जिद","आगरा किले की मोती मस्जिद","लाहौर के शालीमार बाग","सीकरी का बुलंद दरवाजा"],"explanationHi":"बुलंद दरवाजा (लगभग 1575) अकबर ने अपनी गुजरात विजय की स्मृति में बनवाया। शाहजहाँ ने जामा मस्जिद, आगरा किले की मोती मस्जिद और लाहौर के शालीमार बाग बनवाए।"},
  {"id":"history-mughal-81","question":"How many of these officials of Mughal central administration are correctly matched with their charge? I. Diwan – revenue and finance II. Mir Bakhshi – military administration and the mansabdars III. Sadr-us-sudur – religious endowments and charity IV. Muhtasib – censor of public morals","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The diwan handled revenue and finance, the mir bakhshi the military and mansabdars, the sadr-us-sudur religious grants and charity, and the muhtasib enforced public morals and Islamic conduct.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"मुगल केंद्रीय प्रशासन के इन अधिकारियों में से कितने अपने कार्यक्षेत्र से सही सुमेलित हैं? I. दीवान – राजस्व और वित्त II. मीर बख्शी – सैन्य प्रशासन और मनसबदार III. सद्र-उस-सुदूर – धार्मिक अनुदान और दान IV. मुहतसिब – सार्वजनिक नैतिकता का निरीक्षक","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। दीवान राजस्व और वित्त देखता था, मीर बख्शी सेना और मनसबदारों को, सद्र-उस-सुदूर धार्मिक अनुदान और दान को, और मुहतसिब सार्वजनिक नैतिकता तथा इस्लामी आचरण का पालन करवाता था।"},
  {"id":"history-mughal-82","question":"Arrange these events of Akbar’s reign in chronological order: 1. Conquest of Gujarat 2. Battle of Haldighati 3. Capture of Asirgarh 4. Introduction of the Dahsala system","options":["1, 2, 4, 3","2, 1, 4, 3","1, 4, 2, 3","1, 2, 3, 4"],"answer":0,"explanation":"Gujarat conquered 1572–73; Haldighati 1576; Dahsala system 1580; Asirgarh, Akbar’s last conquest, 1601.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अकबर के शासनकाल की इन घटनाओं को कालक्रमानुसार व्यवस्थित कीजिए: 1. गुजरात की विजय 2. हल्दीघाटी का युद्ध 3. असीरगढ़ पर अधिकार 4. दहसाला प्रणाली की शुरुआत","optionsHi":["1, 2, 4, 3","2, 1, 4, 3","1, 4, 2, 3","1, 2, 3, 4"],"explanationHi":"गुजरात की विजय 1572–73; हल्दीघाटी 1576; दहसाला प्रणाली 1580; असीरगढ़, अकबर की अंतिम विजय, 1601।"},
  {"id":"history-mughal-83","question":"How many of these statements about Shah Jahan are correct? I. He founded the city of Shahjahanabad in Delhi. II. The Peacock Throne was made for him. III. The title Shah Jahan was conferred on Prince Khurram by Jahangir after his Deccan campaign. IV. He died in the Agra Fort.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Shah Jahan founded Shahjahanabad, the Peacock Throne was made for him, Jahangir gave Khurram the title after the Deccan campaign, and he died in 1666 in the Agra Fort, where Aurangzeb had confined him.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"शाहजहाँ के बारे में इनमें से कितने कथन सही हैं? I. उसने दिल्ली में शाहजहानाबाद नगर की स्थापना की। II. मयूर सिंहासन उसके लिए बनाया गया था। III. शाहजहाँ की उपाधि जहाँगीर ने शहजादे खुर्रम को उसके दक्कन अभियान के बाद दी। IV. उसकी मृत्यु आगरा किले में हुई।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। शाहजहाँ ने शाहजहानाबाद की स्थापना की, मयूर सिंहासन उसके लिए बना, जहाँगीर ने दक्कन अभियान के बाद खुर्रम को यह उपाधि दी, और 1666 में आगरा किले में उसकी मृत्यु हुई, जहाँ औरंगजेब ने उसे कैद रखा था।"},
  {"id":"history-mughal-84","question":"The standard gold coin of the Mughal currency system was the:","options":["Dam","Mohur","Rupiya","Jital"],"answer":1,"explanation":"The gold mohur, the silver rupiya and the copper dam made up the Mughal currency. The jital was a coin of the Delhi Sultanate.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"मुगल मुद्रा प्रणाली का मानक सोने का सिक्का कौन-सा था?","optionsHi":["दाम","मोहर","रुपिया","जीतल"],"explanationHi":"सोने की मोहर, चाँदी का रुपिया और ताँबे का दाम मुगल मुद्रा प्रणाली के अंग थे। जीतल दिल्ली सल्तनत का सिक्का था।"},
  {"id":"history-mughal-85","question":"Which Mughal emperor issued coins showing the signs of the zodiac?","options":["Akbar","Shah Jahan","Aurangzeb","Jahangir"],"answer":3,"explanation":"Jahangir's zodiac coins, each showing the sign of a month, are famous for their artistry. He also issued coins bearing Nur Jahan's name.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"किस मुगल सम्राट ने राशि चक्र के चिह्नों वाले सिक्के जारी किए?","optionsHi":["अकबर","शाहजहाँ","औरंगजेब","जहाँगीर"],"explanationHi":"जहाँगीर के राशि चक्र वाले सिक्के, जिनमें से प्रत्येक पर एक माह की राशि अंकित है, अपनी कलात्मकता के लिए प्रसिद्ध हैं। उसने नूरजहाँ के नाम वाले सिक्के भी जारी किए।"},
  {"id":"history-mughal-86","question":"Mumtaz Mahal, in whose memory the Taj Mahal was built, died in 1631 at:","options":["Agra","Burhanpur","Lahore","Daulatabad"],"answer":1,"explanation":"She died in childbirth at Burhanpur in the Deccan while with Shah Jahan on campaign. Her body was later moved to Agra, where the Taj Mahal was built.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"मुमताज महल, जिनकी स्मृति में ताजमहल बना, की 1631 में मृत्यु कहाँ हुई?","optionsHi":["आगरा","बुरहानपुर","लाहौर","दौलताबाद"],"explanationHi":"वे दक्कन में शाहजहाँ के साथ अभियान के दौरान बुरहानपुर में प्रसव के समय चल बसीं। उनके शव को बाद में आगरा ले जाया गया, जहाँ ताजमहल बना।"},
  {"id":"history-mughal-87","question":"Rani Durgavati, who died fighting the Mughals in 1564, ruled the kingdom of:","options":["Garha-Katanga","Malwa (Mandu)","Mewar (Chittor)","Khandesh"],"answer":0,"explanation":"Durgavati, the regent of Garha-Katanga (Gondwana), fought Akbar's general Asaf Khan and killed herself rather than be captured. Malwa had been taken from Baz Bahadur in 1561.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"रानी दुर्गावती, जो 1564 में मुगलों से लड़ते हुए वीरगति को प्राप्त हुईं, किस राज्य की शासिका थीं?","optionsHi":["गढ़-कटंगा","मालवा (मांडू)","मेवाड़ (चित्तौड़)","खानदेश"],"explanationHi":"गढ़-कटंगा (गोंडवाना) की संरक्षिका दुर्गावती ने अकबर के सेनापति आसफ खाँ से युद्ध किया और पकड़े जाने के बजाय स्वयं प्राण त्याग दिए। मालवा 1561 में बाज बहादुर से छीना गया था।"},
  {"id":"history-mughal-88","question":"The architect chiefly credited with the design of the Taj Mahal is:","options":["Mirak Mirza Ghiyas","Abdul Hamid Lahori","Ustad Mansur","Ustad Ahmad Lahori"],"answer":3,"explanation":"Ustad Ahmad Lahori is usually named as the chief architect of the Taj Mahal, and he also worked on the Red Fort at Delhi. Mirak Mirza Ghiyas designed Humayun's Tomb, and Abdul Hamid Lahori was a historian.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"ताजमहल के डिजाइन का मुख्य श्रेय किस वास्तुकार को दिया जाता है?","optionsHi":["मिराक मिर्जा गियास","अब्दुल हमीद लाहौरी","उस्ताद मंसूर","उस्ताद अहमद लाहौरी"],"explanationHi":"उस्ताद अहमद लाहौरी को सामान्यतः ताजमहल का मुख्य वास्तुकार माना जाता है, और उन्होंने दिल्ली के लाल किले पर भी कार्य किया। मिराक मिर्जा गियास ने हुमायूँ के मकबरे का डिजाइन बनाया था, और अब्दुल हमीद लाहौरी इतिहासकार थे।"},
  {"id":"history-mughal-89","question":"The period 1560–62 of Akbar's reign, when his foster-mother and her relatives dominated the court, is often called the \"petticoat government\". The foster-mother was:","options":["Hamida Banu Begum","Gulbadan Begum","Maham Anaga","Salima Sultan Begum"],"answer":2,"explanation":"Maham Anaga and her son Adham Khan had great influence after Bairam Khan fell. Adham Khan killed the minister Atga Khan in 1562, and Akbar had him thrown from the palace terrace, which ended the phase.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"अकबर के शासन का 1560–62 का वह काल, जब उसकी धात्री माता और उनके संबंधियों का दरबार पर वर्चस्व था, प्रायः \"पेटीकोट सरकार\" कहलाता है। वह धात्री माता कौन थी?","optionsHi":["हमीदा बानो बेगम","गुलबदन बेगम","माहम अनगा","सलीमा सुल्तान बेगम"],"explanationHi":"बैरम खाँ के पतन के बाद माहम अनगा और उसके पुत्र आदम खाँ का बहुत प्रभाव रहा। आदम खाँ ने 1562 में मंत्री अतगा खाँ की हत्या कर दी, और अकबर ने उसे महल की छत से नीचे फिंकवा दिया, जिससे यह दौर समाप्त हुआ।"},
  {"id":"history-mughal-90","question":"The ruler of Malwa, remembered for his romance with Rupmati, who was defeated by Akbar's forces in 1561, was:","options":["Daud Khan","Baz Bahadur","Yusuf Shah Chak","Muzaffar Shah III"],"answer":1,"explanation":"Baz Bahadur lost Malwa to Adham Khan in 1561. Daud Khan Karrani ruled Bengal, Yusuf Shah Chak Kashmir, and Muzaffar Shah III Gujarat.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"मालवा का वह शासक कौन था, जो रूपमती से अपने प्रेम के लिए याद किया जाता है और जिसे 1561 में अकबर की सेना ने पराजित किया?","optionsHi":["दाऊद खाँ","बाज बहादुर","यूसुफ शाह चक","मुजफ्फर शाह तृतीय"],"explanationHi":"बाज बहादुर ने 1561 में आदम खाँ से मालवा खो दिया। दाऊद खाँ कर्रानी ने बंगाल, यूसुफ शाह चक ने कश्मीर और मुजफ्फर शाह तृतीय ने गुजरात पर शासन किया।"},
  {"id":"history-mughal-91","question":"Under the Mughals, the head of a province (suba) was the:","options":["Subedar","Faujdar","Amil","Kotwal"],"answer":0,"explanation":"The subedar (also called sipahsalar or nazim) headed the suba. A diwan in each province handled revenue and reported to the central diwan, which kept a check on the subedar.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"मुगलों के अधीन प्रांत (सूबा) का प्रमुख कौन होता था?","optionsHi":["सूबेदार","फौजदार","अमील","कोतवाल"],"explanationHi":"सूबेदार (जिसे सिपहसालार या नाजिम भी कहा जाता था) सूबे का प्रमुख होता था। प्रत्येक प्रांत में एक दीवान राजस्व संभालता था और केंद्रीय दीवान को रिपोर्ट करता था, जिससे सूबेदार पर नियंत्रण रहता था।"},
  {"id":"history-mughal-92","question":"Abul Fazl was murdered in 1602 by Bir Singh Bundela at the instigation of:","options":["Prince Daniyal","Prince Murad","Prince Khusrau","Prince Salim"],"answer":3,"explanation":"Prince Salim, the future Jahangir, was in revolt and saw Abul Fazl as his enemy, so he had Bir Singh Deo Bundela ambush him on his way back from the Deccan. Bir Singh later rose high under Jahangir.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"1602 में अबुल फजल की हत्या बीर सिंह बुंदेला ने किसके उकसावे पर की?","optionsHi":["शहजादा दानियाल","शहजादा मुराद","शहजादा खुसरो","शहजादा सलीम"],"explanationHi":"भावी जहाँगीर, शहजादा सलीम, विद्रोह में था और अबुल फजल को अपना शत्रु मानता था, इसलिए उसने बीर सिंह देव बुंदेला से दक्कन से लौटते समय उन पर घात लगवाया। बीर सिंह को बाद में जहाँगीर के अधीन उच्च पद मिला।"},
  {"id":"history-mughal-93","question":"Birbal, one of Akbar's best-known courtiers, was killed in 1586 while fighting:","options":["Rana Pratap's Rajputs in Mewar","Yusufzai Afghans of the north-west","The Ahoms in the Brahmaputra valley","The Deccan sultanate of Ahmadnagar"],"answer":1,"explanation":"Birbal died in an ambush in the Swat region during the campaign against the Yusufzai tribesmen, and Akbar is said to have mourned him deeply.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"अकबर के सबसे प्रसिद्ध दरबारियों में से एक बीरबल 1586 में किससे लड़ते हुए मारे गए?","optionsHi":["मेवाड़ में राणा प्रताप के राजपूतों से","उत्तर-पश्चिम के यूसुफजई अफगानों से","ब्रह्मपुत्र घाटी के अहोमों से","अहमदनगर की दक्कनी सल्तनत से"],"explanationHi":"बीरबल यूसुफजई कबीलों के विरुद्ध अभियान के दौरान स्वात क्षेत्र में घात में मारे गए, और कहा जाता है कि अकबर ने उनके निधन पर गहरा शोक मनाया।"},
  {"id":"history-mughal-94","question":"Daud Khan Karrani, the Afghan ruler of Bengal, was defeated and killed by Akbar's forces in 1576 at the Battle of:","options":["Tukaroi","Sarnal","Rajmahal","Haldighati"],"answer":2,"explanation":"His defeat at Rajmahal (July 1576) brought Bengal under the Mughals. Tukaroi (1575) was an earlier defeat for him, Sarnal (1572) was fought in Akbar's Gujarat campaign, and Haldighati (June 1576) was against Rana Pratap.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"बंगाल के अफगान शासक दाऊद खाँ कर्रानी को 1576 में अकबर की सेना ने किस युद्ध में पराजित कर मार डाला?","optionsHi":["तुकारोई","सरनाल","राजमहल","हल्दीघाटी"],"explanationHi":"राजमहल (जुलाई 1576) में उसकी पराजय से बंगाल मुगलों के अधीन आ गया। तुकारोई (1575) में उसकी पहले पराजय हुई थी, सरनाल (1572) अकबर के गुजरात अभियान में लड़ा गया, और हल्दीघाटी (जून 1576) राणा प्रताप के विरुद्ध था।"},
  {"id":"history-mughal-95","question":"In 1626 a Mughal general seized Jahangir on the banks of the Jhelum in a coup against Nur Jahan's faction. The general was:","options":["Asaf Khan","Mahabat Khan","Khan-i-Khanan Abdur Rahim","Ali Mardan Khan"],"answer":1,"explanation":"Mahabat Khan held the emperor for some months before Nur Jahan's tactics freed him. Asaf Khan was Nur Jahan's brother and Shah Jahan's father-in-law.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"1626 में एक मुगल सेनापति ने नूरजहाँ के गुट के विरुद्ध तख्तापलट में झेलम के तट पर जहाँगीर को पकड़ लिया। वह सेनापति कौन था?","optionsHi":["आसफ खाँ","महाबत खाँ","खान-ए-खानाँ अब्दुर्रहीम","अली मर्दान खाँ"],"explanationHi":"महाबत खाँ ने सम्राट को कुछ महीने अपने नियंत्रण में रखा, फिर नूरजहाँ की चतुराई से वे मुक्त हुए। आसफ खाँ नूरजहाँ का भाई और शाहजहाँ का ससुर था।"},
  {"id":"history-mughal-96","question":"Shah Jahan's costly and unsuccessful campaign of 1646–47 in Central Asia, led by Princes Murad and Aurangzeb, was aimed at:","options":["Kandahar and Bust","Kabul and Ghazni","Herat and Persian Khurasan","Balkh and Badakhshan"],"answer":3,"explanation":"Shah Jahan hoped to win back the Timurid homeland, but the Mughals had to withdraw from Balkh at great cost. The three failed sieges of Kandahar came later (1649–53).","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"शहजादों मुराद और औरंगजेब के नेतृत्व में शाहजहाँ का 1646–47 का महँगा और असफल मध्य एशियाई अभियान किसे जीतने के लिए था?","optionsHi":["कंधार और बस्त","काबुल और गजनी","हेरात और फारसी खुरासान","बल्ख और बदख्शाँ"],"explanationHi":"शाहजहाँ को तैमूरी मातृभूमि वापस जीतने की आशा थी, परंतु मुगलों को भारी कीमत चुकाकर बल्ख से हटना पड़ा। कंधार की तीन असफल घेराबंदियाँ बाद में (1649–53) हुईं।"},
  {"id":"history-mughal-97","question":"The \"Alamgirnama\", the official history of the first ten years of Aurangzeb's reign, was written by:","options":["Muhammad Hashim Khafi Khan","Saqi Mustaid Khan","Mirza Muhammad Kazim","Abdul Hamid Lahori"],"answer":2,"explanation":"Mirza Muhammad Kazim wrote the Alamgirnama, and Aurangzeb then stopped official history-writing. Saqi Mustaid Khan wrote the Maasir-i-Alamgiri after his death, and Khafi Khan wrote the Muntakhab-ul-Lubab privately.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"औरंगजेब के शासन के प्रथम दस वर्षों का आधिकारिक इतिहास “आलमगीरनामा” किसने लिखा?","optionsHi":["मुहम्मद हाशिम खफी खाँ","साकी मुस्तैद खाँ","मिर्जा मुहम्मद काजिम","अब्दुल हमीद लाहौरी"],"explanationHi":"आलमगीरनामा मिर्जा मुहम्मद काजिम ने लिखा, जिसके बाद औरंगजेब ने आधिकारिक इतिहास-लेखन बंद करवा दिया। साकी मुस्तैद खाँ ने उसकी मृत्यु के बाद मआसिर-ए-आलमगीरी लिखा, और खफी खाँ ने मुंतखब-उल-लुबाब निजी तौर पर लिखा।"},
  {"id":"history-mughal-98","question":"Shivaji escaped from Mughal custody at Agra in:","options":["1666","1660","1674","1680"],"answer":0,"explanation":"After the Treaty of Purandar (1665), Shivaji went to Aurangzeb's court in 1666, was kept under house arrest, and escaped in August 1666. He was crowned in 1674 and died in 1680.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"शिवाजी आगरा में मुगल हिरासत से कब बच निकले?","optionsHi":["1666","1660","1674","1680"],"explanationHi":"पुरंदर की संधि (1665) के बाद शिवाजी 1666 में औरंगजेब के दरबार गए, उन्हें नजरबंद रखा गया, और वे अगस्त 1666 में बच निकले। उनका राज्याभिषेक 1674 में हुआ और 1680 में उनका निधन हुआ।"},
  {"id":"history-mughal-99","question":"Which son of Aurangzeb rebelled in 1681 in alliance with the Rajputs and later took refuge with the Maratha king Sambhaji?","options":["Prince Muazzam","Prince Akbar","Prince Azam","Prince Kam Bakhsh"],"answer":1,"explanation":"Prince Akbar declared himself emperor in 1681 during the Rajput war. When his attempt failed he fled to Sambhaji and later to Persia, and this drew Aurangzeb into the Deccan for good.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"औरंगजेब के किस पुत्र ने 1681 में राजपूतों के साथ मिलकर विद्रोह किया और बाद में मराठा राजा संभाजी की शरण ली?","optionsHi":["शहजादा मुअज्जम","शहजादा अकबर","शहजादा आजम","शहजादा काम बख्श"],"explanationHi":"शहजादा अकबर ने 1681 में राजपूत युद्ध के दौरान स्वयं को सम्राट घोषित कर दिया। प्रयास विफल होने पर वह संभाजी और फिर फारस भाग गया, और इसी कारण औरंगजेब सदा के लिए दक्कन में उलझ गया।"},
  {"id":"history-mughal-100","question":"Humayun's Tomb in Delhi was designed by the Persian architect:","options":["Ustad Ahmad Lahori","Ustad Isa","Mir Abdul Karim","Mirak Mirza Ghiyas"],"answer":3,"explanation":"Mirak Mirza Ghiyas designed the tomb (built about 1565–72), which was commissioned after Humayun's death by his widow Bega Begum. It was the first great garden-tomb and a model for the Taj.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"दिल्ली में हुमायूँ के मकबरे का डिजाइन किस फारसी वास्तुकार ने बनाया था?","optionsHi":["उस्ताद अहमद लाहौरी","उस्ताद ईसा","मीर अब्दुल करीम","मिराक मिर्जा गियास"],"explanationHi":"मिराक मिर्जा गियास ने इस मकबरे (लगभग 1565–72 में निर्मित) का डिजाइन बनाया, जिसे हुमायूँ की मृत्यु के बाद उसकी विधवा बेगा बेगम ने बनवाने का आदेश दिया। यह पहला महान उद्यान-मकबरा और ताज के लिए आदर्श था।"},
  {"id":"history-mughal-101","question":"Chand Bibi is remembered for defending which fort against the Mughals in 1595?","options":["Asirgarh","Daulatabad","Ahmadnagar","Golconda"],"answer":2,"explanation":"Chand Bibi, regent of Ahmadnagar, held off Prince Murad's siege in 1595. She was killed in 1600, after which the Mughals took the fort.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"1595 में मुगलों के विरुद्ध किस किले की रक्षा के लिए चाँद बीबी को याद किया जाता है?","optionsHi":["असीरगढ़","दौलताबाद","अहमदनगर","गोलकुंडा"],"explanationHi":"अहमदनगर की संरक्षिका चाँद बीबी ने 1595 में शहजादा मुराद की घेराबंदी को रोके रखा। 1600 में उनकी हत्या कर दी गई, जिसके बाद मुगलों ने किले पर अधिकार कर लिया।"},
  {"id":"history-mughal-102","question":"Match the land category of Akbar's revenue system with its description: A. Polaj B. Parauti C. Chachar D. Banjar. 1. Land left fallow for five years or more 2. Land left fallow for three or four years 3. Land cultivated every year 4. Land left fallow for a short time to recover its fertility","options":["A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2"],"answer":0,"explanation":"Polaj was cultivated continuously and parauti rested briefly. Chachar lay fallow three or four years and banjar five years or more. Revenue was charged in full on polaj and on parauti when cropped, with concessions on chachar and banjar.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अकबर की राजस्व प्रणाली की भूमि श्रेणी का उसके विवरण से मिलान कीजिए: A. पोलज B. परौती C. चाचर D. बंजर। 1. पाँच या अधिक वर्षों तक परती छोड़ी गई भूमि 2. तीन या चार वर्ष परती छोड़ी गई भूमि 3. प्रतिवर्ष जोती जाने वाली भूमि 4. उर्वरता लौटाने के लिए थोड़े समय परती छोड़ी गई भूमि","optionsHi":["A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2"],"explanationHi":"पोलज में निरंतर खेती होती थी और परौती को थोड़े समय विश्राम दिया जाता था। चाचर तीन या चार वर्ष और बंजर पाँच या अधिक वर्ष परती रहती थी। पोलज पर तथा बुआई होने पर परौती पर पूरा राजस्व लगता था, जबकि चाचर और बंजर पर रियायत मिलती थी।"},
  {"id":"history-mughal-103","question":"Match the Mughal local official with the charge: A. Faujdar B. Kotwal C. Amalguzar D. Qanungo. 1. Keeper of land records at the pargana level 2. Revenue collector of a sarkar (district) 3. Police and administration of a town 4. Law and order and military command in a sarkar","options":["A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"The faujdar kept order in a sarkar, the kotwal ran a town, the amalguzar collected revenue in a sarkar, and the qanungo kept the land records of a pargana.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"मुगल स्थानीय अधिकारी का उसके कार्य से मिलान कीजिए: A. फौजदार B. कोतवाल C. अमलगुजार D. कानूनगो। 1. परगना स्तर पर भूमि अभिलेखों का रखवाला 2. सरकार (जिला) का राजस्व संग्राहक 3. नगर की पुलिस और प्रशासन 4. सरकार में कानून-व्यवस्था और सैन्य कमान","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1"],"explanationHi":"फौजदार सरकार में व्यवस्था बनाए रखता था, कोतवाल नगर चलाता था, अमलगुजार सरकार में राजस्व वसूलता था, और कानूनगो परगने के भूमि अभिलेख रखता था।"},
  {"id":"history-mughal-104","question":"Arrange these events concerning Kandahar in chronological order: 1. Shah Jahan recovers Kandahar through the defection of its Persian governor Ali Mardan Khan 2. Kandahar is lost to Shah Abbas I of Persia 3. Akbar acquires Kandahar 4. Kandahar is finally lost to the Persians","options":["3, 2, 1, 4","2, 3, 1, 4","3, 1, 2, 4","3, 2, 4, 1"],"answer":0,"explanation":"Akbar took Kandahar in 1595, and it was lost to Shah Abbas in 1622 under Jahangir. Shah Jahan regained it in 1638 and lost it for good in 1649; three later sieges failed.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"कंधार से संबंधित इन घटनाओं को कालक्रमानुसार व्यवस्थित कीजिए: 1. शाहजहाँ ने फारसी गवर्नर अली मर्दान खाँ के पक्ष बदलने से कंधार पुनः प्राप्त किया 2. फारस के शाह अब्बास प्रथम के हाथों कंधार का खो जाना 3. अकबर द्वारा कंधार की प्राप्ति 4. कंधार का अंततः फारसियों के हाथों चला जाना","optionsHi":["3, 2, 1, 4","2, 3, 1, 4","3, 1, 2, 4","3, 2, 4, 1"],"explanationHi":"अकबर ने 1595 में कंधार लिया, और जहाँगीर के काल में 1622 में यह शाह अब्बास के हाथों चला गया। शाहजहाँ ने इसे 1638 में पुनः प्राप्त किया और 1649 में सदा के लिए खो दिया; बाद की तीन घेराबंदियाँ विफल रहीं।"},
  {"id":"history-mughal-105","question":"How many of these were among Aurangzeb's measures? I. He stopped the practice of jharokha darshan. II. He forbade inscribing the kalma on coins. III. He gave up the ceremony of weighing the emperor against gold and silver (tuladan). IV. He banned the celebration of Nauroz.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four were his measures, part of his effort to bring court practice in line with his reading of Islamic law. He also reimposed jizya in 1679 and appointed muhtasibs to enforce public morals.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने औरंगजेब के उपाय थे? I. उसने झरोखा दर्शन की प्रथा बंद की। II. उसने सिक्कों पर कलमा अंकित करने पर रोक लगाई। III. उसने सम्राट को सोने-चाँदी से तौलने की रस्म (तुलादान) त्याग दी। IV. उसने नौरोज के उत्सव पर प्रतिबंध लगाया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों उसके उपाय थे, जो दरबारी रीति-रिवाजों को इस्लामी कानून की अपनी समझ के अनुरूप बनाने के उसके प्रयास का हिस्सा थे। उसने 1679 में जजिया भी फिर से लगाया और सार्वजनिक नैतिकता लागू करने के लिए मुहतसिब नियुक्त किए।"},
  {"id":"history-mughal-106","question":"Assertion (A): Mewar accepted Mughal suzerainty in 1615 without Rana Amar Singh having to appear in person at the Mughal court. Reason (R): Jahangir excused the Rana from personal attendance, and his son Karan Singh went to court instead.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"After Prince Khurram's campaign, Jahangir offered generous terms: Chittor was returned, the Rana did not have to attend court, and Karan Singh received a mansab. R explains how A came about.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): मेवाड़ ने 1615 में मुगल अधीनता स्वीकार कर ली, जबकि राणा अमर सिंह को स्वयं मुगल दरबार में उपस्थित नहीं होना पड़ा। कारण (R): जहाँगीर ने राणा को व्यक्तिगत उपस्थिति से छूट दे दी, और उसके स्थान पर उसका पुत्र कर्ण सिंह दरबार गया।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, किंतु R, A की सही व्याख्या नहीं है","A सत्य है, किंतु R असत्य है","A असत्य है, किंतु R सत्य है"],"explanationHi":"शहजादे खुर्रम के अभियान के बाद जहाँगीर ने उदार शर्तें रखीं: चित्तौड़ लौटा दिया गया, राणा को दरबार में उपस्थित नहीं होना था, और कर्ण सिंह को मनसब मिला। R यह स्पष्ट करता है कि A कैसे संभव हुआ।"},
  {"id":"history-mughal-107","question":"Match the revolt against Aurangzeb with its leader or region: A. Jat revolt B. Satnami revolt C. Bundela resistance D. Rathor resistance. 1. Durgadas, in Marwar 2. Chhatrasal, in Bundelkhand 3. Narnaul, 1672 4. Gokula, near Mathura, 1669","options":["A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1"],"answer":1,"explanation":"Gokula led the Jats near Mathura in 1669, and the Satnamis rose at Narnaul in 1672. Chhatrasal carved out a Bundela kingdom, and Durgadas Rathor fought for the infant Ajit Singh of Marwar.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"औरंगजेब के विरुद्ध विद्रोह का उसके नेता या क्षेत्र से मिलान कीजिए: A. जाट विद्रोह B. सतनामी विद्रोह C. बुंदेला प्रतिरोध D. राठौड़ प्रतिरोध। 1. दुर्गादास, मारवाड़ में 2. छत्रसाल, बुंदेलखंड में 3. नारनौल, 1672 4. गोकुला, मथुरा के निकट, 1669","optionsHi":["A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1"],"explanationHi":"गोकुला ने 1669 में मथुरा के निकट जाटों का नेतृत्व किया, और सतनामियों ने 1672 में नारनौल में विद्रोह किया। छत्रसाल ने बुंदेला राज्य स्थापित किया, और दुर्गादास राठौड़ ने मारवाड़ के शिशु अजीत सिंह के लिए संघर्ष किया।"},
  {"id":"history-mughal-108","question":"Arrange in chronological order: 1. Fall of the Sayyid brothers 2. Nadir Shah's invasion 3. Farrukhsiyar's farman to the English Company 4. Death of Bahadur Shah I","options":["3, 4, 1, 2","4, 1, 3, 2","4, 3, 1, 2","4, 3, 2, 1"],"answer":2,"explanation":"Bahadur Shah I died in 1712, and Farrukhsiyar granted the farman in 1717. The Sayyid brothers, the king-makers, fell in 1720 under Muhammad Shah, and Nadir Shah sacked Delhi in 1739.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. सैयद बंधुओं का पतन 2. नादिर शाह का आक्रमण 3. अंग्रेज कंपनी को फर्रुखसियर का फरमान 4. बहादुर शाह प्रथम की मृत्यु","optionsHi":["3, 4, 1, 2","4, 1, 3, 2","4, 3, 1, 2","4, 3, 2, 1"],"explanationHi":"बहादुर शाह प्रथम की मृत्यु 1712 में हुई और फर्रुखसियर ने 1717 में फरमान दिया। बादशाह बनाने वाले सैयद बंधुओं का पतन 1720 में मुहम्मद शाह के अधीन हुआ, और नादिर शाह ने 1739 में दिल्ली को लूटा।"},
  {"id":"history-mughal-109","question":"How many of these statements about Dara Shikoh are correct? I. He wrote the Majma-ul-Bahrain, comparing Sufi and Vedantic ideas. II. He had fifty Upanishads translated into Persian as the Sirr-i-Akbar. III. He was defeated by Aurangzeb and Murad at Samugarh in 1658. IV. He was executed on the orders of Shah Jahan.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Dara was Shah Jahan's favourite son. After his final defeat at Deorai (1659) he was captured and executed on Aurangzeb's orders.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"दारा शिकोह के बारे में इनमें से कितने कथन सही हैं? I. उसने मज्मा-उल-बहरैन लिखी, जिसमें सूफी और वेदांती विचारों की तुलना की गई है। II. उसने पचास उपनिषदों का फारसी में अनुवाद सिर्र-ए-अकबर के रूप में करवाया। III. 1658 में सामूगढ़ में औरंगजेब और मुराद ने उसे पराजित किया। IV. उसे शाहजहाँ के आदेश पर मृत्युदंड दिया गया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। दारा शाहजहाँ का प्रिय पुत्र था। देवराई (1659) में अंतिम पराजय के बाद उसे पकड़ लिया गया और औरंगजेब के आदेश पर मृत्युदंड दिया गया।"},
  {"id":"history-mughal-110","question":"Match the method of revenue assessment used under the Mughals with its description: A. Zabt B. Ghallabakhshi (batai) C. Nasaq D. Kankut. 1. Sharing the actual produce between the state and the peasant 2. A rough assessment based on the peasant's past payments 3. Measuring the land and applying fixed cash rates for each crop 4. Estimating the yield by inspecting the standing crop","options":["A-3, B-1, C-4, D-2","A-1, B-3, C-2, D-4","A-3, B-2, C-1, D-4","A-3, B-1, C-2, D-4"],"answer":3,"explanation":"Zabt rested on measurement and cash rates (dasturs) and was used in the core provinces. Batai shared the crop. Nasaq was a rough calculation from past receipts, and kankut an estimate of yield made in the field.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"मुगलों के अधीन प्रयुक्त राजस्व निर्धारण की पद्धति का उसके विवरण से मिलान कीजिए: A. जब्त B. गल्लाबख्शी (बटाई) C. नसक D. कनकूत। 1. राज्य और किसान के बीच वास्तविक उपज का बँटवारा 2. किसान के पिछले भुगतानों पर आधारित मोटा आकलन 3. भूमि की पैमाइश कर प्रत्येक फसल के लिए निश्चित नकद दरें लगाना 4. खड़ी फसल का निरीक्षण कर उपज का अनुमान लगाना","optionsHi":["A-3, B-1, C-4, D-2","A-1, B-3, C-2, D-4","A-3, B-2, C-1, D-4","A-3, B-1, C-2, D-4"],"explanationHi":"जब्त पैमाइश और नकद दरों (दस्तूर) पर आधारित था और मुख्य प्रांतों में प्रयुक्त होता था। बटाई में फसल का बँटवारा होता था। नसक पिछली प्राप्तियों से मोटा हिसाब था, और कनकूत खेत में किया गया उपज का अनुमान।"},
  {"id":"history-mughal-111","question":"Match the painter with the description: A. Ustad Mansur B. Abul Hasan C. Bishandas D. Daswanth. 1. Given the title Nadir-uz-Zaman by Jahangir 2. Given the title Nadir-ul-Asr; famous for painting birds and animals 3. Sent with Jahangir's embassy to Persia to paint portraits of Shah Abbas 4. A painter of Akbar's workshop who worked on the Razmnama","options":["A-2, B-1, C-3, D-4","A-1, B-2, C-3, D-4","A-2, B-1, C-4, D-3","A-2, B-3, C-1, D-4"],"answer":0,"explanation":"Jahangir gave Mansur the title Nadir-ul-Asr (wonder of the age) and Abul Hasan the title Nadir-uz-Zaman. He sent Bishandas to Persia with his embassy. Daswanth was one of the leading painters of Akbar's Razmnama.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"चित्रकार का उसके विवरण से मिलान कीजिए: A. उस्ताद मंसूर B. अबुल हसन C. बिशनदास D. दसवंत। 1. जहाँगीर द्वारा नादिर-उज-जमाँ की उपाधि दी गई 2. नादिर-उल-अस्र की उपाधि प्राप्त; पक्षियों और पशुओं के चित्रण के लिए प्रसिद्ध 3. शाह अब्बास के व्यक्ति-चित्र बनाने के लिए जहाँगीर के दूतमंडल के साथ फारस भेजा गया 4. अकबर की चित्रशाला का चित्रकार जिसने रज्मनामा पर कार्य किया","optionsHi":["A-2, B-1, C-3, D-4","A-1, B-2, C-3, D-4","A-2, B-1, C-4, D-3","A-2, B-3, C-1, D-4"],"explanationHi":"जहाँगीर ने मंसूर को नादिर-उल-अस्र (युग का आश्चर्य) और अबुल हसन को नादिर-उज-जमाँ की उपाधि दी। उसने बिशनदास को अपने दूतमंडल के साथ फारस भेजा। दसवंत अकबर के रज्मनामा के प्रमुख चित्रकारों में से एक थे।"},
  {"id":"history-mughal-112","question":"How many of these statements about Mughal provincial administration are correct? I. In 1580 Akbar divided the empire into twelve subas. II. By the end of his reign Berar, Khandesh and Ahmadnagar had raised the number to fifteen. III. Each suba had a diwan for revenue who reported to the central diwan. IV. A pargana was a larger unit than a sarkar.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV reverses the order: a suba was divided into sarkars, and each sarkar into parganas.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"मुगल प्रांतीय प्रशासन के बारे में इनमें से कितने कथन सही हैं? I. 1580 में अकबर ने साम्राज्य को बारह सूबों में बाँटा। II. उसके शासन के अंत तक बरार, खानदेश और अहमदनगर के जुड़ने से यह संख्या पंद्रह हो गई। III. प्रत्येक सूबे में राजस्व के लिए एक दीवान होता था जो केंद्रीय दीवान को रिपोर्ट करता था। IV. परगना, सरकार से बड़ी इकाई थी।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV क्रम को उलट देता है: सूबा सरकारों में और प्रत्येक सरकार परगनों में बँटी होती थी।"},
  {"id":"history-mughal-113","question":"Assertion (A): Humayun was able to win back his throne in 1555, fifteen years after losing it to Sher Shah. Reason (R): With troops from Shah Tahmasp of Persia he took Kandahar and Kabul, and he then exploited the quarrels among Sher Shah's successors.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Persian help gave Humayun a base in Kandahar and Kabul, and the break-up of the Sur empire after Islam Shah's death (1553) opened the way. He won at Machhiwara and Sirhind in 1555.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): हुमायूँ शेरशाह के हाथों गद्दी खोने के पंद्रह वर्ष बाद, 1555 में, उसे वापस पाने में सफल रहा। कारण (R): फारस के शाह तहमास्प की सेना की सहायता से उसने कंधार और काबुल जीते, और फिर शेरशाह के उत्तराधिकारियों के आपसी झगड़ों का लाभ उठाया।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, किंतु R, A की सही व्याख्या नहीं है","A सत्य है, किंतु R असत्य है","A असत्य है, किंतु R सत्य है"],"explanationHi":"फारसी सहायता ने हुमायूँ को कंधार और काबुल में आधार दिया, और इस्लाम शाह की मृत्यु (1553) के बाद सूर साम्राज्य के बिखराव ने मार्ग खोल दिया। उसने 1555 में मच्छीवाड़ा और सरहिंद में विजय पाई।"},
  {"id":"history-mughal-114","question":"Sher Shah Suri rebuilt the great road from Sonargaon in Bengal to Peshawar, which later came to be known as the:","options":["Northern Silk Road","Grand Trunk Road","Uttarapatha","Dakshinapatha"],"answer":1,"explanation":"Sher Shah's Sadak-e-Azam, with sarais at regular intervals, later became the Grand Trunk Road. Uttarapatha was the ancient northern trade route.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"शेरशाह सूरी ने बंगाल के सोनारगाँव से पेशावर तक की जिस महान सड़क का पुनर्निर्माण करवाया, वह बाद में किस नाम से जानी गई?","optionsHi":["उत्तरी रेशम मार्ग","ग्रैंड ट्रंक रोड","उत्तरापथ","दक्षिणापथ"],"explanationHi":"शेरशाह की सड़क-ए-आजम, जिस पर नियमित अंतराल पर सराय बनी थीं, बाद में ग्रैंड ट्रंक रोड बनी। उत्तरापथ प्राचीन उत्तरी व्यापार मार्ग था।"},
  {"id":"history-mughal-115","question":"Which Mughal emperor took the title “Alamgir” (conqueror of the world)?","options":["Aurangzeb","Shah Jahan","Jahangir","Bahadur Shah I"],"answer":0,"explanation":"Aurangzeb crowned himself Alamgir in 1658–59. Jahangir means “world-seizer” and was Salim's title.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"किस मुगल सम्राट ने “आलमगीर” (विश्व-विजेता) की उपाधि धारण की?","optionsHi":["औरंगजेब","शाहजहाँ","जहाँगीर","बहादुर शाह प्रथम"],"explanationHi":"औरंगजेब ने 1658–59 में स्वयं को आलमगीर घोषित किया। जहाँगीर का अर्थ “विश्व को जीतने वाला” है और यह सलीम की उपाधि थी।"},
  {"id":"history-mughal-116","question":"Akbar built Fatehpur Sikri near the hermitage of the Sufi saint:","options":["Shaikh Nizamuddin Auliya","Moinuddin Chishti","Bakhtiyar Kaki","Shaikh Salim Chishti"],"answer":3,"explanation":"Akbar believed Shaikh Salim Chishti's blessings brought him a son, Salim (Jahangir), and built his new capital at Sikri, where the saint's tomb stands.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"अकबर ने फतेहपुर सीकरी का निर्माण किस सूफी संत की कुटिया के निकट करवाया?","optionsHi":["शेख निजामुद्दीन औलिया","मोइनुद्दीन चिश्ती","बख्तियार काकी","शेख सलीम चिश्ती"],"explanationHi":"अकबर का विश्वास था कि शेख सलीम चिश्ती के आशीर्वाद से उसे पुत्र सलीम (जहाँगीर) प्राप्त हुआ, और उसने सीकरी में, जहाँ संत का मकबरा है, अपनी नई राजधानी बनवाई।"},
  {"id":"history-mughal-117","question":"Under Sher Shah, the document given to each peasant stating the land and the revenue due, and the deed of acceptance signed by the peasant, were called:","options":["Patta and qabuliyat","Farman and parwana","Dastur-ul-amal and jama","Zabt and nasaq"],"answer":0,"explanation":"The patta recorded the state's claim and the qabuliyat was the peasant's acceptance. Akbar continued the practice.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"शेरशाह के अधीन प्रत्येक किसान को दिया जाने वाला वह दस्तावेज, जिसमें भूमि और देय राजस्व लिखा होता था, तथा किसान द्वारा हस्ताक्षरित स्वीकृति-पत्र क्या कहलाते थे?","optionsHi":["पट्टा और कबूलियत","फरमान और परवाना","दस्तूर-उल-अमल और जमा","जब्त और नसक"],"explanationHi":"पट्टे में राज्य का दावा दर्ज होता था और कबूलियत किसान की स्वीकृति थी। अकबर ने यह प्रथा जारी रखी।"},
  {"id":"history-mughal-118","question":"Nadir Shah defeated the Mughal army at Karnal and sacked Delhi in 1739 during the reign of:","options":["Farrukhsiyar","Muhammad Shah","Ahmad Shah Bahadur","Alamgir II"],"answer":1,"explanation":"Muhammad Shah “Rangila” (1719–48) was emperor when Nadir Shah carried off the Peacock Throne and the Kohinoor.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"नादिर शाह ने 1739 में किसके शासनकाल में करनाल में मुगल सेना को हराया और दिल्ली को लूटा?","optionsHi":["फर्रुखसियर","मुहम्मद शाह","अहमद शाह बहादुर","आलमगीर द्वितीय"],"explanationHi":"मुहम्मद शाह “रंगीला” (1719–48) सम्राट थे जब नादिर शाह मयूर सिंहासन और कोहिनूर ले गया।"},
  {"id":"history-mughal-119","question":"Akbar abolished the jizya in:","options":["1556","1575","1582","1564"],"answer":3,"explanation":"Akbar abolished the pilgrim tax in 1563 and the jizya in 1564. Aurangzeb reimposed the jizya in 1679.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"अकबर ने जजिया कब समाप्त किया?","optionsHi":["1556","1575","1582","1564"],"explanationHi":"अकबर ने 1563 में तीर्थ यात्रा कर और 1564 में जजिया समाप्त किया। औरंगजेब ने 1679 में जजिया फिर से लगाया।"},
  {"id":"history-mughal-120","question":"The Sikh leader Banda Singh Bahadur was captured and executed in Delhi in 1716 during the reign of:","options":["Bahadur Shah I","Jahandar Shah","Farrukhsiyar","Muhammad Shah"],"answer":2,"explanation":"Farrukhsiyar's forces captured Banda at Gurdas Nangal. Banda had earlier set up Sikh rule in Punjab after Guru Gobind Singh's death in 1708.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"सिख नेता बंदा सिंह बहादुर को 1716 में किसके शासनकाल में पकड़कर दिल्ली में मृत्युदंड दिया गया?","optionsHi":["बहादुर शाह प्रथम","जहाँदार शाह","फर्रुखसियर","मुहम्मद शाह"],"explanationHi":"फर्रुखसियर की सेना ने बंदा को गुरदास नंगल में पकड़ा। बंदा ने इससे पहले 1708 में गुरु गोबिंद सिंह की मृत्यु के बाद पंजाब में सिख शासन स्थापित किया था।"},
  {"id":"history-mughal-121","question":"Guru Gobind Singh founded the Khalsa in 1699 at:","options":["Amritsar","Nanded","Anandpur Sahib","Talwandi Sabo (Damdama)"],"answer":2,"explanation":"The Khalsa was created at Anandpur on Baisakhi 1699, during Aurangzeb's reign. Guru Gobind Singh later finalised the Adi Granth at Damdama Sahib (Talwandi Sabo) and died at Nanded in 1708.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"गुरु गोबिंद सिंह ने 1699 में खालसा की स्थापना कहाँ की?","optionsHi":["अमृतसर","नांदेड़","आनंदपुर साहिब","तलवंडी साबो (दमदमा)"],"explanationHi":"खालसा की रचना औरंगजेब के शासनकाल में 1699 की बैसाखी पर आनंदपुर में हुई। गुरु गोबिंद सिंह ने बाद में दमदमा साहिब (तलवंडी साबो) में आदि ग्रंथ को अंतिम रूप दिया और 1708 में नांदेड़ में उनका निधन हुआ।"},
  {"id":"history-mughal-122","question":"The system of “du-aspa sih-aspa” rank, letting selected mansabdars maintain more troopers without a higher zat, was introduced by:","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb"],"answer":1,"explanation":"Jahangir introduced du-aspa sih-aspa (two- and three-horse troopers). Mahabat Khan was among the first to receive it.","difficulty":"hard","source":"UPSC Prelims","questionHi":"“दो-अस्पा सिह-अस्पा” पद की प्रणाली, जिसमें चुने हुए मनसबदारों को जात बढ़ाए बिना अधिक घुड़सवार रखने की अनुमति थी, किसने शुरू की?","optionsHi":["अकबर","जहाँगीर","शाहजहाँ","औरंगजेब"],"explanationHi":"जहाँगीर ने दो-अस्पा सिह-अस्पा (दो और तीन घोड़ों वाले सवार) शुरू किया। महाबत खाँ इसे पाने वाले पहले लोगों में से थे।"},
  {"id":"history-mughal-123","question":"In the Mughal revenue system, “khalisa” land was land whose revenue:","options":["Was assigned to mansabdars as jagir","Went directly to the imperial treasury","Was granted to scholars and holy men","Was collected by zamindars for themselves"],"answer":1,"explanation":"Khalisa was crown land administered directly for the emperor. Jagirs paid mansabdars, and madad-i-maash grants supported scholars and religious men.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मुगल राजस्व प्रणाली में “खालिसा” भूमि वह भूमि थी जिसका राजस्व:","optionsHi":["मनसबदारों को जागीर के रूप में दिया जाता था","सीधे शाही खजाने में जाता था","विद्वानों और संतों को अनुदान में दिया जाता था","जमींदार अपने लिए वसूलते थे"],"explanationHi":"खालिसा ताज की भूमि थी जो सम्राट के लिए सीधे प्रशासित होती थी। जागीरें मनसबदारों को वेतन के बदले दी जाती थीं, और मदद-ए-माश अनुदान विद्वानों तथा धार्मिक व्यक्तियों का भरण-पोषण करते थे।"},
  {"id":"history-mughal-124","question":"Under the Mughals, “madad-i-maash” grants were:","options":["Loans to peasants for seed and cattle","Revenue-free land for scholars and the pious","Cash salaries paid to mansabdars instead of jagirs","Taxes on trade passing through towns"],"answer":1,"explanation":"Madad-i-maash (also suyurghal) were revenue-free grants for maintenance of learned and pious persons. Loans to cultivators were called taqavi.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मुगलों के अधीन “मदद-ए-माश” अनुदान क्या थे?","optionsHi":["बीज और पशुओं के लिए किसानों को ऋण","विद्वानों और धर्मपरायण लोगों के लिए राजस्व-मुक्त भूमि","जागीर के बदले मनसबदारों को दिया जाने वाला नकद वेतन","नगरों से गुजरने वाले व्यापार पर कर"],"explanationHi":"मदद-ए-माश (जिन्हें सुयुरगल भी कहा जाता था) विद्वान और धर्मपरायण व्यक्तियों के भरण-पोषण हेतु राजस्व-मुक्त अनुदान थे। कृषकों को दिए जाने वाले ऋण तकावी कहलाते थे।"},
  {"id":"history-mughal-125","question":"The first Jesuit mission from Goa, including Rudolf Acquaviva and Antonio Monserrate, reached Akbar's court in:","options":["1562","1572","1595","1580"],"answer":3,"explanation":"The first mission arrived in 1580, soon after the Ibadat Khana debates were opened to all faiths. Monserrate later wrote an account of Akbar's court.","difficulty":"hard","source":"UPSC Prelims","questionHi":"गोवा से आया पहला जेसुइट मिशन, जिसमें रुडोल्फ एक्वाविवा और एंटोनियो मॉन्सेराट शामिल थे, अकबर के दरबार में कब पहुँचा?","optionsHi":["1562","1572","1595","1580"],"explanationHi":"पहला मिशन 1580 में आया, इबादतखाना की बहसें सभी धर्मों के लिए खोले जाने के कुछ समय बाद। मॉन्सेराट ने बाद में अकबर के दरबार का विवरण लिखा।"},
  {"id":"history-mughal-126","question":"The English merchant who travelled through India in Akbar's reign and described Agra and Fatehpur Sikri was:","options":["Ralph Fitch","William Hawkins","Sir Thomas Roe","Peter Mundy"],"answer":0,"explanation":"Ralph Fitch travelled in the 1580s. Hawkins and Roe visited Jahangir, and Peter Mundy came in Shah Jahan's reign.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अकबर के शासनकाल में भारत की यात्रा करने और आगरा तथा फतेहपुर सीकरी का वर्णन करने वाला अंग्रेज व्यापारी कौन था?","optionsHi":["राल्फ फिच","विलियम हॉकिन्स","सर थॉमस रो","पीटर मुंडी"],"explanationHi":"राल्फ फिच ने 1580 के दशक में यात्रा की। हॉकिन्स और रो जहाँगीर के पास आए, और पीटर मुंडी शाहजहाँ के शासनकाल में आया।"},
  {"id":"history-mughal-127","question":"In the Battle of Saraighat (1671), the Mughal army under Raja Ram Singh was defeated by the Ahom general:","options":["Lachit Borphukan","Atan Burhagohain","Rudra Singha","Momai Tamuli"],"answer":0,"explanation":"Lachit Borphukan's naval victory on the Brahmaputra near Guwahati stopped Mughal expansion into Assam. Atan Burhagohain was the Ahom prime minister of the time, and Rudra Singha a later Ahom king.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"सराईघाट के युद्ध (1671) में राजा राम सिंह के नेतृत्व वाली मुगल सेना को किस अहोम सेनापति ने पराजित किया?","optionsHi":["लाचित बोरफुकन","अतन बुरहागोहाईं","रुद्र सिंह","मोमाई तामुली"],"explanationHi":"गुवाहाटी के निकट ब्रह्मपुत्र पर लाचित बोरफुकन की नौसैनिक विजय ने असम में मुगल विस्तार को रोक दिया। अतन बुरहागोहाईं उस समय अहोम प्रधानमंत्री थे, और रुद्र सिंह बाद के अहोम राजा।"},
  {"id":"history-mughal-128","question":"Mir Jumla, who led Aurangzeb's invasion of Assam in 1662, had earlier been the chief minister of:","options":["Bijapur","Golconda","Ahmadnagar","Bengal"],"answer":1,"explanation":"Mir Jumla, a Persian diamond merchant, was wazir of Golconda before joining the Mughals; he gave Shah Jahan a famous diamond and later served Aurangzeb as governor of Bengal.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मीर जुमला, जिसने 1662 में औरंगजेब के असम आक्रमण का नेतृत्व किया, इससे पहले किसका प्रधानमंत्री रह चुका था?","optionsHi":["बीजापुर","गोलकुंडा","अहमदनगर","बंगाल"],"explanationHi":"फारसी हीरा व्यापारी मीर जुमला मुगलों में शामिल होने से पहले गोलकुंडा का वजीर था; उसने शाहजहाँ को एक प्रसिद्ध हीरा भेंट किया और बाद में औरंगजेब के अधीन बंगाल का गवर्नर रहा।"},
  {"id":"history-mughal-129","question":"The English East India Company received permission to set up a permanent factory at Surat in 1613 from:","options":["Akbar","Shah Jahan","Jahangir","Aurangzeb"],"answer":2,"explanation":"Jahangir's farman followed Thomas Best's naval victory over the Portuguese at Swally (1612). Thomas Roe later secured wider privileges.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"इंग्लिश ईस्ट इंडिया कंपनी को 1613 में सूरत में स्थायी कोठी स्थापित करने की अनुमति किसने दी?","optionsHi":["अकबर","शाहजहाँ","जहाँगीर","औरंगजेब"],"explanationHi":"जहाँगीर का फरमान स्वाली (1612) में पुर्तगालियों पर थॉमस बेस्ट की नौसैनिक विजय के बाद आया। थॉमस रो ने बाद में व्यापक विशेषाधिकार प्राप्त किए।"},
  {"id":"history-mughal-130","question":"Early in his reign Aurangzeb abolished which of these levies?","options":["Jizya and the pilgrim tax","Rahdari and pandari","Kharaj and ushr","Zakat and khams"],"answer":1,"explanation":"Aurangzeb abolished rahdari (transit dues) and pandari (ground rent), which burdened trade, though officials often kept collecting them. He reimposed, not abolished, the jizya.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अपने शासन के आरंभ में औरंगजेब ने इनमें से कौन-से कर समाप्त किए?","optionsHi":["जजिया और तीर्थ यात्रा कर","राहदारी और पंडरी","खराज और उश्र","जकात और खम्स"],"explanationHi":"औरंगजेब ने राहदारी (पारगमन शुल्क) और पंडरी (भूमि किराया) समाप्त किए, जो व्यापार पर बोझ थे, यद्यपि अधिकारी प्रायः इन्हें वसूलते रहे। उसने जजिया समाप्त नहीं, बल्कि फिर से लगाया था।"},
  {"id":"history-mughal-131","question":"Which Sikh Guru built the Akal Takht at Amritsar and adopted a martial stance against the Mughals?","options":["Guru Arjan Dev","Guru Hargobind","Guru Har Rai","Guru Tegh Bahadur"],"answer":1,"explanation":"Guru Hargobind, son of the martyred Guru Arjan, wore two swords (miri and piri), built the Akal Takht and fought Mughal forces in Shah Jahan's reign.","difficulty":"hard","source":"SSC CGL · State PSCs","questionHi":"किस सिख गुरु ने अमृतसर में अकाल तख्त बनवाया और मुगलों के प्रति सैन्य रुख अपनाया?","optionsHi":["गुरु अर्जन देव","गुरु हरगोबिंद","गुरु हर राय","गुरु तेग बहादुर"],"explanationHi":"शहीद गुरु अर्जन के पुत्र गुरु हरगोबिंद ने दो तलवारें (मीरी और पीरी) धारण कीं, अकाल तख्त बनवाया और शाहजहाँ के शासनकाल में मुगल सेनाओं से युद्ध किया।"},
  {"id":"history-mughal-132","question":"Arrange these annexations of Akbar in chronological order: 1. Kashmir 2. Sindh 3. Malwa 4. Chittor","options":["3, 4, 2, 1","4, 3, 1, 2","3, 1, 4, 2","3, 4, 1, 2"],"answer":3,"explanation":"Malwa (1561), Chittor (1568), Kashmir (1586) and Sindh (1591).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अकबर द्वारा किए गए इन विलयों को कालक्रमानुसार व्यवस्थित कीजिए: 1. कश्मीर 2. सिंध 3. मालवा 4. चित्तौड़","optionsHi":["3, 4, 2, 1","4, 3, 1, 2","3, 1, 4, 2","3, 4, 1, 2"],"explanationHi":"मालवा (1561), चित्तौड़ (1568), कश्मीर (1586) और सिंध (1591)।"},
  {"id":"history-mughal-133","question":"Match the Mughal emperor with the place of his tomb: A. Babur B. Humayun C. Akbar D. Jahangir — 1. Shahdara, Lahore 2. Kabul 3. Sikandra 4. Delhi","options":["A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-1, D-3"],"answer":0,"explanation":"Babur lies in the Bagh-e-Babur at Kabul, Humayun in Delhi, Akbar at Sikandra near Agra and Jahangir at Shahdara near Lahore.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"मुगल सम्राट का उसके मकबरे के स्थान से मिलान कीजिए: A. बाबर B. हुमायूँ C. अकबर D. जहाँगीर — 1. शाहदरा, लाहौर 2. काबुल 3. सिकंदरा 4. दिल्ली","optionsHi":["A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-1, D-3"],"explanationHi":"बाबर काबुल के बाग-ए-बाबर में, हुमायूँ दिल्ली में, अकबर आगरा के निकट सिकंदरा में और जहाँगीर लाहौर के निकट शाहदरा में दफन हैं।"},
  {"id":"history-mughal-134","question":"Consider the following statements: 1. The Moti Masjid inside the Red Fort, Delhi was built by Aurangzeb. 2. The Moti Masjid in the Agra Fort was built by Shah Jahan. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. Aurangzeb built the small marble Moti Masjid for his private prayers in the Red Fort; Shah Jahan built the larger one at Agra.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. दिल्ली के लाल किले के भीतर की मोती मस्जिद औरंगजेब ने बनवाई थी। 2. आगरा किले की मोती मस्जिद शाहजहाँ ने बनवाई थी। उपर्युक्त में से कौन-सा/से कथन सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। औरंगजेब ने अपनी निजी इबादत के लिए लाल किले में छोटी संगमरमर की मोती मस्जिद बनवाई; शाहजहाँ ने आगरा में बड़ी मस्जिद बनवाई।"},
  {"id":"history-mughal-135","question":"Assertion (A): Mughal mansabdars did not become a hereditary landed aristocracy. Reason (R): Jagirs were regularly transferred and a mansab was not inherited; a mansabdar's assets could be resumed by the state at his death.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. Transfers and escheat kept nobles dependent on the emperor, unlike the hereditary iqtas of Firoz Shah's time.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): मुगल मनसबदार एक वंशानुगत भूस्वामी अभिजात वर्ग नहीं बन पाए। कारण (R): जागीरों का नियमित स्थानांतरण होता था और मनसब विरासत में नहीं मिलता था; मनसबदार की मृत्यु पर उसकी संपत्ति राज्य द्वारा जब्त की जा सकती थी।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, किंतु R, A की सही व्याख्या नहीं है","A सत्य है, किंतु R असत्य है","A असत्य है, किंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है। स्थानांतरण और संपत्ति-अधिग्रहण ने सरदारों को सम्राट पर निर्भर रखा, जो फिरोज शाह के समय के वंशानुगत इक्ताओं से भिन्न था।"},
  {"id":"history-mughal-136","question":"Consider the following statements: 1. Sher Shah fixed the state's share at one-third of the average produce, worked out through crop-wise schedules of rates. 2. Raja Todar Mal, who later built Akbar's revenue system, had earlier served under Sher Shah. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. Todar Mal worked for Sher Shah (including on Rohtas fort in Punjab) and later shaped Akbar's zabt system.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. शेरशाह ने राज्य का हिस्सा औसत उपज का एक-तिहाई निर्धारित किया, जिसकी गणना फसलवार दर-सूचियों से की जाती थी। 2. राजा टोडरमल, जिन्होंने बाद में अकबर की राजस्व प्रणाली बनाई, पहले शेरशाह के अधीन कार्य कर चुके थे। उपर्युक्त में से कौन-सा/से कथन सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। टोडरमल ने शेरशाह के लिए (पंजाब के रोहतास किले सहित) कार्य किया और बाद में अकबर की जब्ती प्रणाली को आकार दिया।"},
  {"id":"history-mughal-137","question":"How many of these statements about Nur Jahan are correct? I. She built the tomb of her father, Itimad-ud-Daulah, at Agra. II. Coins were struck in her name. III. She was the mother of Shah Jahan. IV. She tried to resist Mahabat Khan's seizure of Jahangir in 1626.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. Shah Jahan (Khurram) was the son of Jahangir's Rajput wife; Nur Jahan's niece, Mumtaz Mahal, was his wife.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"नूरजहाँ के बारे में इनमें से कितने कथन सही हैं? I. उन्होंने आगरा में अपने पिता इतिमादुद्दौला का मकबरा बनवाया। II. उनके नाम से सिक्के ढाले गए। III. वे शाहजहाँ की माता थीं। IV. 1626 में महाबत खाँ द्वारा जहाँगीर को पकड़े जाने का उन्होंने प्रतिरोध करने का प्रयास किया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। शाहजहाँ (खुर्रम) जहाँगीर की राजपूत पत्नी का पुत्र था; नूरजहाँ की भतीजी मुमताज महल उसकी पत्नी थीं।"},
  {"id":"history-mughal-138","question":"Arrange in chronological order: 1. Sir Thomas Roe reaches Jahangir's court 2. First Jesuit mission at Akbar's court 3. Jahangir's farman for the English factory at Surat 4. Shah Jahan expels the Portuguese from Hugli","options":["2, 1, 3, 4","2, 3, 4, 1","2, 3, 1, 4","3, 2, 1, 4"],"answer":2,"explanation":"Jesuit mission (1580), Surat farman (1613), Roe at court (1615–19) and Hugli (1632).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. सर थॉमस रो का जहाँगीर के दरबार में पहुँचना 2. अकबर के दरबार में पहला जेसुइट मिशन 3. सूरत में अंग्रेजी कोठी के लिए जहाँगीर का फरमान 4. शाहजहाँ द्वारा पुर्तगालियों को हुगली से निकालना","optionsHi":["2, 1, 3, 4","2, 3, 4, 1","2, 3, 1, 4","3, 2, 1, 4"],"explanationHi":"जेसुइट मिशन (1580), सूरत का फरमान (1613), रो का दरबार में आना (1615–19) और हुगली (1632)।"},
  {"id":"history-mughal-139","question":"The Persian translation of the Baburnama completed in 1589 at Akbar's order was the work of:","options":["Abul Fazl","Faizi","Abdur Rahim Khan-i-Khanan","Abdul Qadir Badauni"],"answer":2,"explanation":"Babur wrote his memoirs in Chagatai Turki. Abdur Rahim Khan-i-Khanan, son of Bairam Khan, rendered it into Persian in 1589, so the Mughal court could read the founder's own account.","difficulty":"hard","questionHi":"1589 में अकबर के आदेश पर पूर्ण हुआ बाबरनामा का फारसी अनुवाद किसका कार्य था?","optionsHi":["अबुल फजल","फैजी","अब्दुर्रहीम खान-ए-खाना","अब्दुल कादिर बदायूँनी"],"explanationHi":"बाबर ने अपने संस्मरण चगताई तुर्की में लिखे थे। बैरम खाँ के पुत्र अब्दुर्रहीम खान-ए-खाना ने 1589 में इसका फारसी अनुवाद किया, जिससे मुगल दरबार संस्थापक का स्वयं लिखा वृत्तांत पढ़ सके।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-140","question":"After his victory over Rana Sanga at Khanwa (1527), Babur assumed the title of:","options":["Ghazi","Sahib-i-Qiran","Alamgir","Zinda Pir"],"answer":0,"explanation":"Babur had declared the war a jihad against the Rajputs and took the title Ghazi after the victory. Sahib-i-Qiran was Timur's title, Alamgir was Aurangzeb's, and Zinda Pir a nickname of Aurangzeb.","difficulty":"hard","questionHi":"खानवा (1527) में राणा सांगा पर विजय के बाद बाबर ने कौन-सी उपाधि धारण की?","optionsHi":["गाजी","साहिब-ए-किरान","आलमगीर","जिंदा पीर"],"explanationHi":"बाबर ने इस युद्ध को राजपूतों के विरुद्ध जिहाद घोषित किया था और विजय के बाद गाजी की उपाधि ली। साहिब-ए-किरान तैमूर की उपाधि थी, आलमगीर औरंगजेब की और जिंदा पीर औरंगजेब का उपनाम था।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-mughal-141","question":"Farid, the future Sher Shah, received the title 'Sher Khan' for killing a tiger while in the service of:","options":["Jamal Khan of Jaunpur","Bahar Khan Lohani of Bihar","Ibrahim Lodi of Delhi","Babur of Delhi"],"answer":1,"explanation":"Farid rose in Bihar under Bahar Khan Lohani (Sultan Muhammad), who gave him the title Sher Khan. After Chausa (1539) he took the title Sher Shah.","difficulty":"very-hard","questionHi":"भावी शेरशाह फरीद को बाघ मारने पर 'शेर खाँ' की उपाधि किसकी सेवा में रहते हुए मिली?","optionsHi":["जौनपुर के जमाल खाँ","बिहार के बहार खाँ लोहानी","दिल्ली के इब्राहीम लोदी","दिल्ली के बाबर"],"explanationHi":"फरीद बिहार में बहार खाँ लोहानी (सुल्तान मुहम्मद) के अधीन आगे बढ़ा, जिसने उसे शेर खाँ की उपाधि दी। चौसा (1539) के बाद उसने शेरशाह की उपाधि ली।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-142","question":"The city Din-Panah, founded by Humayun in 1533 on the banks of the Yamuna at Delhi, later became the site of which fort?","options":["Purana Qila","Red Fort","Tughlaqabad","Siri"],"answer":0,"explanation":"Humayun's Din-Panah was built at the site that Sher Shah rebuilt as the Purana Qila (Shergarh). The Red Fort came with Shah Jahan.","difficulty":"moderate","questionHi":"1533 में हुमायूँ द्वारा दिल्ली में यमुना किनारे बसाया गया दीन-पनाह नगर बाद में किस किले का स्थल बना?","optionsHi":["पुराना किला","लाल किला","तुगलकाबाद","सीरी"],"explanationHi":"हुमायूँ का दीन-पनाह उसी स्थान पर बना था जिसे शेरशाह ने पुराने किले (शेरगढ़) के रूप में पुनः बनवाया। लाल किला शाहजहाँ के समय बना।","source":"SSC CGL · State PCS"},
  {"id":"history-mughal-143","question":"Babur assumed the title of Padshah in 1507, while he was ruling from:","options":["Samarkand","Ferghana","Kandahar","Kabul"],"answer":3,"explanation":"After losing Samarkand and Ferghana, Babur took Kabul in 1504 and in 1507 took the title Padshah there, so the Timurid title predates the Indian conquest.","difficulty":"hard","questionHi":"बाबर ने 1507 में पादशाह की उपाधि धारण की, उस समय वह कहाँ से शासन कर रहा था?","optionsHi":["समरकंद","फरगना","कंधार","काबुल"],"explanationHi":"समरकंद और फरगना खोने के बाद बाबर ने 1504 में काबुल जीता और 1507 में वहीं पादशाह की उपाधि ली, अतः यह तैमूरी उपाधि भारत-विजय से पहले की है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-144","question":"Akbar's standard unit of land measurement, the 'Ilahi gaz', replaced the earlier standard known as the:","options":["Shahjahani gaz","Sikandari gaz","Alamgiri gaz","Jahangiri gaz"],"answer":1,"explanation":"The Sikandari gaz of the Lodi sultan Sikandar was the older yard. Akbar's Ilahi gaz (about 33 inches) became the standard in revenue measurement.","difficulty":"very-hard","questionHi":"अकबर की भूमि-माप की मानक इकाई 'इलाही गज' ने किस पूर्ववर्ती माप का स्थान लिया?","optionsHi":["शाहजहानी गज","सिकंदरी गज","आलमगीरी गज","जहाँगीरी गज"],"explanationHi":"लोदी सुल्तान सिकंदर का सिकंदरी गज पुराना मानक था। अकबर का इलाही गज (लगभग 33 इंच) राजस्व माप का मानक बन गया।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-145","question":"In 1585 Akbar left Fatehpur Sikri and moved his capital to:","options":["Agra","Delhi","Allahabad","Lahore"],"answer":3,"explanation":"Akbar shifted to Lahore to watch the north-west frontier after the Kabul trouble and the Uzbek threat, and stayed there until 1598, when he returned to Agra.","difficulty":"moderate","questionHi":"1585 में अकबर ने फतेहपुर सीकरी छोड़कर अपनी राजधानी कहाँ स्थानांतरित की?","optionsHi":["आगरा","दिल्ली","इलाहाबाद","लाहौर"],"explanationHi":"काबुल की समस्या और उजबेक खतरे के बाद उत्तर-पश्चिमी सीमा पर नजर रखने के लिए अकबर लाहौर चले गए और 1598 तक वहीं रहे, जब वे आगरा लौटे।","source":"SSC CGL · State PCS"},
  {"id":"history-mughal-146","question":"Before joining Akbar's court in 1562, the musician Tansen was in the service of the Baghela ruler Ramchandra of:","options":["Rewa","Gwalior","Orchha","Jaipur"],"answer":0,"explanation":"Tansen, a Gwalior-trained singer of dhrupad, served Raja Ramchandra of Rewa, who sent him to Akbar's court in about 1562.","difficulty":"hard","questionHi":"1562 में अकबर के दरबार में आने से पहले संगीतज्ञ तानसेन बघेल शासक रामचंद्र की सेवा में कहाँ थे?","optionsHi":["रीवा","ग्वालियर","ओरछा","जयपुर"],"explanationHi":"ग्वालियर में प्रशिक्षित ध्रुपद गायक तानसेन रीवा के राजा रामचंद्र की सेवा में थे, जिन्होंने उन्हें लगभग 1562 में अकबर के दरबार में भेजा।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-147","question":"In the Mughal jagir system, 'paibaqi' land was:","options":["Land whose revenue went directly into the imperial treasury","Rent-free land granted to scholars and holy men","Land kept unassigned in reserve for allotment as jagirs later","The home farm that a zamindar cultivated for himself"],"answer":2,"explanation":"Paibaqi was the pool of land not yet assigned and held ready for future jagirs. Khalisa was the Crown land, madad-i-maash the rent-free grants and nankar the zamindar's own land.","difficulty":"very-hard","questionHi":"मुगल जागीर प्रणाली में 'पाईबाकी' भूमि क्या थी?","optionsHi":["वह भूमि जिसका राजस्व सीधे शाही खजाने में जाता था","विद्वानों और संतों को दी गई कर-मुक्त भूमि","वह भूमि जिसे बाद में जागीर के रूप में देने के लिए आरक्षित रखा जाता था","वह खेत जिसे जमींदार अपने लिए जोतता था"],"explanationHi":"पाईबाकी उस भूमि का भंडार थी जो अभी बाँटी नहीं गई थी और भावी जागीरों के लिए रखी जाती थी। खालिसा ताज की भूमि थी, मदद-ए-माश कर-मुक्त अनुदान और नानकार जमींदार की अपनी भूमि।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-148","question":"Malik Ambar, the Abyssinian regent of Ahmadnagar who resisted the Mughals, founded the city of Khirki, later renamed:","options":["Hyderabad","Burhanpur","Aurangabad","Gulbarga"],"answer":2,"explanation":"Malik Ambar founded Khirki in about 1610, and Aurangzeb, as Deccan viceroy, later made it his base and gave it the name Aurangabad.","difficulty":"hard","questionHi":"अहमदनगर के हब्शी संरक्षक मलिक अंबर, जिसने मुगलों का प्रतिरोध किया, ने खिड़की नगर बसाया, जिसका नाम बाद में क्या पड़ा?","optionsHi":["हैदराबाद","बुरहानपुर","औरंगाबाद","गुलबर्गा"],"explanationHi":"मलिक अंबर ने लगभग 1610 में खिड़की बसाया और औरंगजेब ने दक्कन के सूबेदार के रूप में इसे अपना अड्डा बनाकर इसका नाम औरंगाबाद रखा।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-149","question":"The Nizam Shahi dynasty of Ahmadnagar was finally extinguished, and the kingdom absorbed into the empire, in 1633 under:","options":["Akbar","Jahangir","Shah Jahan","Aurangzeb"],"answer":2,"explanation":"Akbar had taken the fort in 1600 but the dynasty survived under Malik Ambar. Shah Jahan's forces ended it in 1633 and imprisoned the boy king at Gwalior.","difficulty":"moderate","questionHi":"अहमदनगर का निजामशाही वंश 1633 में अंततः किसके समय समाप्त हुआ और राज्य साम्राज्य में मिला लिया गया?","optionsHi":["अकबर","जहाँगीर","शाहजहाँ","औरंगजेब"],"explanationHi":"अकबर ने 1600 में किला ले लिया था पर वंश मलिक अंबर के अधीन बचा रहा। शाहजहाँ की सेना ने 1633 में इसे समाप्त किया और बालक राजा को ग्वालियर में बंदी बनाया।","source":"SSC CGL · State PCS"},
  {"id":"history-mughal-150","question":"The 'Muntakhab-ul-Lubab', a detailed history of the Mughals down to Muhammad Shah that was compiled secretly because Aurangzeb discouraged history writing, is by:","options":["Saqi Mustaid Khan","Khafi Khan","Bakhtawar Khan","Abdul Hamid Lahori"],"answer":1,"explanation":"Khafi Khan wrote it in secret, so the name is a pseudonym. Saqi Mustaid wrote the Maasir-i-Alamgiri after Aurangzeb's death and Lahori the Padshahnama.","difficulty":"hard","questionHi":"मुहम्मद शाह तक के मुगलों का विस्तृत इतिहास 'मुंतखब-उल-लुबाब', जो गुप्त रूप से लिखा गया क्योंकि औरंगजेब ने इतिहास-लेखन को हतोत्साहित किया था, किसकी रचना है?","optionsHi":["साकी मुस्तैद खाँ","खफी खाँ","बख्तावर खाँ","अब्दुल हमीद लाहौरी"],"explanationHi":"खफी खाँ ने इसे गुप्त रूप से लिखा, इसलिए यह नाम छद्म नाम है। साकी मुस्तैद ने औरंगजेब की मृत्यु के बाद मआसिर-ए-आलमगीरी लिखी और लाहौरी ने पादशाहनामा।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-151","question":"Match the foreign traveller with his description: A. François Bernier B. Jean-Baptiste Tavernier C. Niccolao Manucci D. Peter Mundy. 1. French jeweller and gem trader 2. French physician who stayed at Danishmand Khan's household 3. Venetian who served in Dara Shikoh's artillery 4. English merchant who recorded the famine of 1630-31","options":["A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4","A-2, B-1, C-4, D-3","A-3, B-1, C-2, D-4"],"answer":1,"explanation":"Bernier was a physician (with Danishmand Khan), Tavernier a jeweller, Manucci a Venetian in Dara's service and Mundy an English merchant at Agra during the Gujarat-Deccan famine.","difficulty":"very-hard","questionHi":"विदेशी यात्री का उसके विवरण से मिलान कीजिए: A. फ्रांस्वा बर्नियर B. ज्याँ-बैप्टिस्ट टैवर्नियर C. निकोलाओ मनूची D. पीटर मुंडी। 1. फ्रांसीसी जौहरी और रत्न व्यापारी 2. फ्रांसीसी चिकित्सक जो दानिशमंद खाँ के घर में रहे 3. वेनिस का निवासी जिसने दारा शिकोह के तोपखाने में सेवा की 4. अंग्रेज व्यापारी जिसने 1630-31 के अकाल का वर्णन किया","optionsHi":["A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4","A-2, B-1, C-4, D-3","A-3, B-1, C-2, D-4"],"explanationHi":"बर्नियर चिकित्सक थे (दानिशमंद खाँ के साथ), टैवर्नियर जौहरी, मनूची दारा की सेवा में वेनिस का निवासी और मुंडी आगरा में रहने वाला अंग्रेज व्यापारी जिसने गुजरात-दक्कन के अकाल का वर्णन किया।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-152","question":"The historian Khafi Khan described which later Mughal emperor as 'Shah-i-Bekhabar' (the heedless king)?","options":["Jahandar Shah","Farrukhsiyar","Bahadur Shah I","Muhammad Shah"],"answer":2,"explanation":"Bahadur Shah I (1707-12), a mild and careless ruler, was given this nickname. Muhammad Shah is known by the nickname Rangila.","difficulty":"very-hard","questionHi":"इतिहासकार खफी खाँ ने किस परवर्ती मुगल सम्राट को 'शाह-ए-बेखबर' (बेपरवाह बादशाह) कहा?","optionsHi":["जहाँदार शाह","फर्रुखसियर","बहादुर शाह प्रथम","मुहम्मद शाह"],"explanationHi":"बहादुर शाह प्रथम (1707-12) को, जो नरम और लापरवाह शासक था, यह उपनाम मिला। मुहम्मद शाह रंगीला उपनाम से जाना जाता है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-153","question":"The Nishat Bagh on the Dal Lake at Srinagar was laid out by:","options":["Jahangir","Asaf Khan","Shah Jahan","Nur Jahan"],"answer":1,"explanation":"Asaf Khan, brother of Nur Jahan and father-in-law of Shah Jahan, built the Nishat Bagh in 1633. Jahangir's own garden was the Shalimar Bagh.","difficulty":"hard","questionHi":"श्रीनगर में डल झील पर निशात बाग किसने बनवाया?","optionsHi":["जहाँगीर","आसफ खाँ","शाहजहाँ","नूरजहाँ"],"explanationHi":"नूरजहाँ के भाई और शाहजहाँ के ससुर आसफ खाँ ने 1633 में निशात बाग बनवाया। जहाँगीर का अपना बाग शालीमार बाग था।","source":"State PCS · SSC CGL"},
  {"id":"history-mughal-154","question":"Sawai Jai Singh II built astronomical observatories (Jantar Mantar) at all the following places EXCEPT:","options":["Delhi","Varanasi","Ujjain","Hyderabad"],"answer":3,"explanation":"Jai Singh built observatories at Delhi, Jaipur, Ujjain, Varanasi and Mathura, using his Zij-i-Muhammad Shahi. None was built at Hyderabad.","difficulty":"hard","questionHi":"सवाई जयसिंह द्वितीय ने निम्नलिखित सभी स्थानों पर खगोलीय वेधशालाएँ (जंतर-मंतर) बनवाईं, केवल एक को छोड़कर:","optionsHi":["दिल्ली","वाराणसी","उज्जैन","हैदराबाद"],"explanationHi":"जयसिंह ने दिल्ली, जयपुर, उज्जैन, वाराणसी और मथुरा में वेधशालाएँ बनवाईं और अपनी जीज-ए-मुहम्मदशाही का उपयोग किया। हैदराबाद में कोई वेधशाला नहीं बनी।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-155","question":"In Sher Shah's pargana administration, the 'Amin' was the officer in charge of:","options":["Keeping the pargana treasury","Maintaining law and order with the troops","Recording accounts in Hindi and Persian","Land measurement and revenue assessment"],"answer":3,"explanation":"The Amin dealt with measurement and assessment of land revenue, while the Shiqdar kept order, the Fotedar held the treasury and the two Karkuns wrote the accounts in Hindi and Persian.","difficulty":"very-hard","questionHi":"शेरशाह की परगना शासन-व्यवस्था में 'अमीन' किस कार्य का प्रभारी अधिकारी था?","optionsHi":["परगने का खजाना रखने का","सेना के साथ कानून-व्यवस्था बनाए रखने का","हिंदी और फारसी में लेखा लिखने का","भूमि की माप और राजस्व निर्धारण का"],"explanationHi":"अमीन भूमि की माप और राजस्व निर्धारण देखता था, जबकि शिकदार व्यवस्था रखता, फोतेदार खजाना संभालता और दो कारकुन हिंदी व फारसी में लेखा लिखते थे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-156","question":"The Himalayan hill fort of Kangra, which had long defied the Mughals, was captured by Jahangir's army in:","options":["1590","1605","1620","1636"],"answer":2,"explanation":"After a siege, Kangra fell to Mughal forces in 1620, and Jahangir visited the fort the next year, though the hill chiefs continued to resist.","difficulty":"hard","questionHi":"हिमालय की तलहटी का कांगड़ा किला, जिसने लंबे समय तक मुगलों का प्रतिरोध किया, जहाँगीर की सेना ने किस वर्ष जीता?","optionsHi":["1590","1605","1620","1636"],"explanationHi":"घेराबंदी के बाद 1620 में कांगड़ा मुगल सेना के हाथ आया और जहाँगीर अगले वर्ष किले में गया, हालाँकि पहाड़ी सरदार प्रतिरोध करते रहे।","source":"State PCS · UPSC Prelims"},
  {"id":"history-mughal-157","question":"'Munis-ul-Arwah', a biography of the Sufi saint Khwaja Moinuddin Chishti, was written by:","options":["Zebunnisa","Gulbadan Begum","Nur Jahan","Jahanara"],"answer":3,"explanation":"Jahanara, Shah Jahan's daughter and a devotee of the Qadiri order, wrote it in about 1640.","difficulty":"hard","questionHi":"सूफी संत ख्वाजा मोईनुद्दीन चिश्ती की जीवनी 'मुनीस-उल-अरवाह' किसने लिखी?","optionsHi":["जेबुन्निसा","गुलबदन बेगम","नूरजहाँ","जहाँआरा"],"explanationHi":"शाहजहाँ की पुत्री और कादिरी संप्रदाय की अनुयायी जहाँआरा ने लगभग 1640 में इसे लिखा।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-158","question":"Murshid Quli Khan, appointed Diwan of Bengal in Aurangzeb's reign, shifted the provincial capital from Dhaka to:","options":["Murshidabad","Calcutta","Patna","Rajmahal"],"answer":0,"explanation":"He moved the Diwani and then the Nizamat to Makhsusabad, renamed Murshidabad after him, and later became virtually independent.","difficulty":"moderate","questionHi":"औरंगजेब के शासनकाल में बंगाल के दीवान नियुक्त मुर्शिद कुली खाँ ने प्रांतीय राजधानी ढाका से कहाँ स्थानांतरित की?","optionsHi":["मुर्शिदाबाद","कलकत्ता","पटना","राजमहल"],"explanationHi":"उसने दीवानी और बाद में निजामत को मखसूसाबाद में स्थानांतरित किया, जिसका नाम उसके नाम पर मुर्शिदाबाद पड़ा, और बाद में वह लगभग स्वतंत्र हो गया।","source":"SSC CGL · State PCS"},
  {"id":"history-mughal-159","question":"How many of these statements about Humayun are correct? I. He was born at Kabul in 1508. II. He founded the city of Din-Panah at Delhi. III. He died from a fall on the staircase of his library in the Purana Qila in 1556. IV. He ruled without a break from 1530 until his death.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. His rule was broken by the exile of 1540-55 after his defeat by Sher Shah.","difficulty":"moderate","questionHi":"हुमायूँ के बारे में इनमें से कितने कथन सही हैं? I. उसका जन्म 1508 में काबुल में हुआ। II. उसने दिल्ली में दीन-पनाह नगर बसाया। III. 1556 में पुराने किले में अपने पुस्तकालय की सीढ़ियों से गिरकर उसकी मृत्यु हुई। IV. उसने 1530 से मृत्यु तक बिना रुकावट शासन किया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। शेरशाह से पराजय के बाद 1540-55 के निर्वासन से उसका शासन बीच में टूटा।","source":"SSC CGL · State PCS"},
  {"id":"history-mughal-160","question":"Assertion (A): Sher Shah's land revenue arrangements are seen as a forerunner of Akbar's. Reason (R): He had cultivated land measured and fixed a schedule of crop rates, which Akbar's officers developed further.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Sher Shah's measurement of land and crop-wise rates, with one-third of the produce as the state share, supplied the base that Todar Mal's zabt later refined.","difficulty":"hard","questionHi":"अभिकथन (A): शेरशाह की भू-राजस्व व्यवस्था को अकबर की व्यवस्था का अग्रगामी माना जाता है। कारण (R): उसने जोती हुई भूमि की पैमाइश कराई और फसलवार दरों की सूची तय की, जिसे अकबर के अधिकारियों ने आगे विकसित किया।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, पर R, A की व्याख्या नहीं करता","A सत्य है, पर R असत्य है","A असत्य है, पर R सत्य है"],"explanationHi":"शेरशाह की भूमि-पैमाइश और फसलवार दरों ने, जिनमें उपज का एक-तिहाई राज्य का भाग था, वह आधार दिया जिसे टोडरमल की जब्ती ने बाद में परिष्कृत किया।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-161","question":"Assertion (A): Akbar's policy towards the Rajputs strengthened the empire. Reason (R): Rajput chiefs were absorbed into the nobility with high ranks and without being forced to give up their faith.","options":["A is true but R is false","Both A and R are true but R does not explain A","Both A and R are true and R explains A","A is false but R is true"],"answer":2,"explanation":"Marriage alliances and high mansabs, along with religious freedom and abolition of the pilgrim tax and jizya, gave Rajputs a stake in the empire and supplied loyal generals.","difficulty":"moderate","questionHi":"अभिकथन (A): राजपूतों के प्रति अकबर की नीति ने साम्राज्य को सुदृढ़ किया। कारण (R): राजपूत सरदारों को अपना धर्म छोड़ने के लिए बाध्य किए बिना ऊँचे मनसबों के साथ अभिजात वर्ग में सम्मिलित किया गया।","optionsHi":["A सत्य है, पर R असत्य है","A और R दोनों सत्य हैं, पर R, A की व्याख्या नहीं करता","A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A असत्य है, पर R सत्य है"],"explanationHi":"वैवाहिक संबंधों और ऊँचे मनसबों के साथ धार्मिक स्वतंत्रता तथा तीर्थयात्रा कर व जजिया की समाप्ति ने राजपूतों को साम्राज्य में हिस्सेदारी दी और निष्ठावान सेनापति उपलब्ध कराए।","source":"SSC CGL · State PCS"},
  {"id":"history-mughal-162","question":"In Akbar's revenue arrangements, which of these regions mainly followed 'nasaq' (assessment based on past practice and rough estimate) rather than the measured zabt?","options":["Bengal","Lahore","Delhi","Allahabad"],"answer":0,"explanation":"Zabt was used chiefly from Lahore to Allahabad and in Malwa and Gujarat. In Bengal, nasaq, based on earlier assessments, continued.","difficulty":"very-hard","questionHi":"अकबर की राजस्व व्यवस्था में इनमें से किस क्षेत्र में मुख्यतः मापी हुई जब्ती के बजाय 'नसक' (पूर्व प्रथा और मोटे अनुमान पर आधारित निर्धारण) चलता था?","optionsHi":["बंगाल","लाहौर","दिल्ली","इलाहाबाद"],"explanationHi":"जब्ती मुख्यतः लाहौर से इलाहाबाद तक तथा मालवा और गुजरात में लागू थी। बंगाल में पूर्व निर्धारणों पर आधारित नसक चलता रहा।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-163","question":"To ease the shortage of jagirs, Shah Jahan reduced the number of sawars a mansabdar had to maintain to:","options":["Double the sawar rank, to enlarge the cavalry","The full sawar rank, with no reduction at all","Nil, by abolishing the sawar rank altogether","A fraction such as one-third of the sawar rank"],"answer":3,"explanation":"From Shah Jahan's time, the contingent actually kept was cut to a fraction of the sawar rank, such as one-third, one-fourth or even one-fifth, to match the available jagirs.","difficulty":"very-hard","questionHi":"जागीरों की कमी दूर करने के लिए शाहजहाँ ने मनसबदार को रखे जाने वाले सवारों की संख्या घटाकर कितनी कर दी?","optionsHi":["सवार पद का दोगुना, घुड़सवार सेना बढ़ाने के लिए","पूरा सवार पद, बिना किसी कटौती के भी","शून्य, सवार पद को पूरी तरह समाप्त करके","सवार पद का एक अंश, जैसे एक-तिहाई"],"explanationHi":"शाहजहाँ के समय से वास्तव में रखी जाने वाली टुकड़ी को उपलब्ध जागीरों के अनुरूप सवार पद के एक अंश, जैसे एक-तिहाई, एक-चौथाई या एक-पाँचवाँ, तक घटा दिया गया।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-164","question":"In Abul Fazl's theory of kingship, the authority of the Mughal emperor rested on 'farr-i-izadi', which he understood as:","options":["A divine light emanating directly from God to the ruler","The consent of the leading nobles of the empire","Descent in the male line from Chinggis Khan","The ritual of showing himself at the jharokha"],"answer":0,"explanation":"Abul Fazl described kingship as a light radiated by God (farr-i-izadi) on the ruler, giving the emperor a role above religious divisions and supporting the policy of sulh-i-kul.","difficulty":"hard","questionHi":"अबुल फजल के राजत्व सिद्धांत में मुगल सम्राट की सत्ता 'फर्र-ए-इजदी' पर आधारित थी, जिसे वह क्या मानता था?","optionsHi":["ईश्वर से सीधे शासक पर पड़ने वाला दिव्य प्रकाश","साम्राज्य के प्रमुख अमीरों की सहमति","चंगेज खाँ से पितृवंशीय वंशज होना","झरोखा दर्शन की रस्म"],"explanationHi":"अबुल फजल ने राजत्व को ईश्वर द्वारा शासक पर डाले गए प्रकाश (फर्र-ए-इजदी) के रूप में बताया, जो सम्राट को धार्मिक भेदों से ऊपर रखता और सुल्ह-ए-कुल की नीति का आधार बनता था।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-165","question":"The defenders of Chittor against Akbar's siege of 1568, remembered in Rajput tradition for their heroism, included:","options":["Man Singh and Bhagwan Das","Jaimal and Patta","Chandrasen and Amar Singh","Rana Pratap and Shakti Singh"],"answer":1,"explanation":"Rana Udai Singh left the fort, which was held by Jaimal Rathore and Patta Sisodia. Jaimal was shot by Akbar and the garrison fell after jauhar and a last sally. Man Singh and Bhagwan Das served the Mughals.","difficulty":"moderate","questionHi":"1568 में अकबर की घेराबंदी के विरुद्ध चित्तौड़ के जो रक्षक राजपूत परंपरा में अपनी वीरता के लिए याद किए जाते हैं, उनमें शामिल थे:","optionsHi":["मानसिंह और भगवानदास","जयमल और पत्ता","चंद्रसेन और अमर सिंह","राणा प्रताप और शक्ति सिंह"],"explanationHi":"राणा उदय सिंह किला छोड़ चुके थे और उसे जयमल राठौर तथा पत्ता सिसोदिया ने सँभाला। अकबर की गोली से जयमल मारे गए और जौहर तथा अंतिम आक्रमण के बाद गढ़ गिर गया। मानसिंह और भगवानदास मुगलों की सेवा में थे।","source":"SSC CGL · State PCS"},
  {"id":"history-mughal-166","question":"Prince Khurram was given the title 'Shah Jahan' by Jahangir in 1617 after his success in the campaign in:","options":["The Mewar campaign","The Kangra campaign","The Deccan, against Malik Ambar","The Kandahar campaign"],"answer":2,"explanation":"Khurram's Deccan campaign of 1616-17 forced the Adil Shah and Nizam Shah to make terms, and Jahangir rewarded him with the title Shah Jahan and a high rank.","difficulty":"hard","questionHi":"राजकुमार खुर्रम को जहाँगीर ने 1617 में किस अभियान में सफलता के बाद 'शाहजहाँ' की उपाधि दी?","optionsHi":["मेवाड़ अभियान","कांगड़ा अभियान","मलिक अंबर के विरुद्ध दक्कन","कंधार अभियान"],"explanationHi":"खुर्रम के 1616-17 के दक्कन अभियान ने आदिलशाह और निजामशाह को समझौते के लिए विवश किया और जहाँगीर ने उसे शाहजहाँ की उपाधि तथा ऊँचा पद दिया।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-167","question":"The 'karori' experiment of 1574 under Akbar involved appointing karoris to:","options":["Command garrisons of one crore troops in the north-west","Collect revenue from tracts expected to yield about one crore dams each","Audit the accounts of jagirdars in each province","Settle disputes among zamindars of a pargana"],"answer":1,"explanation":"Karoris were revenue officers placed in charge of a tract expected to yield one karor (crore) dams, to collect and check the revenue and get the land surveyed. Faults of the arrangement led to the later zabt.","difficulty":"very-hard","questionHi":"अकबर के 1574 के 'करोड़ी' प्रयोग में करोड़ियों की नियुक्ति किस उद्देश्य से हुई?","optionsHi":["उत्तर-पश्चिम में एक करोड़ सैनिकों वाली चौकियों की कमान सँभालने के लिए","लगभग एक करोड़ दाम उपज देने वाले प्रत्येक क्षेत्र से राजस्व वसूलने के लिए","प्रत्येक प्रांत में जागीरदारों के लेखे की जाँच के लिए","परगने के जमींदारों के विवाद सुलझाने के लिए"],"explanationHi":"करोड़ी ऐसे राजस्व अधिकारी थे जिन्हें लगभग एक करोड़ दाम उपज देने वाले क्षेत्र का भार दिया गया, ताकि वे राजस्व वसूलें, जाँचें और भूमि की पैमाइश कराएँ। इस व्यवस्था की त्रुटियों से बाद में जब्ती निकली।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-168","question":"The leader of the Baro-Bhuiyans, the Bengal chieftains who resisted Akbar's generals in the east, was:","options":["Daud Khan Karrani","Isa Khan","Pratapaditya","Man Singh"],"answer":1,"explanation":"Isa Khan of Sonargaon led the Bhuiyans and held out against Man Singh's campaigns. Daud Karrani was the Afghan sultan killed in 1576 and Man Singh was Akbar's general.","difficulty":"hard","questionHi":"बंगाल के सरदारों 'बारो-भुइयाँ', जिन्होंने पूर्व में अकबर के सेनापतियों का प्रतिरोध किया, का नेता कौन था?","optionsHi":["दाऊद खाँ करार्रानी","ईसा खाँ","प्रतापादित्य","मानसिंह"],"explanationHi":"सोनारगाँव के ईसा खाँ ने भुइयाँ का नेतृत्व किया और मानसिंह के अभियानों के सामने डटे रहे। दाऊद करार्रानी 1576 में मारा गया अफगान सुल्तान था और मानसिंह अकबर का सेनापति।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-169","question":"In 1581 Akbar marched to Kabul to deal with his half-brother who had invaded the Punjab. He was:","options":["Kamran Mirza","Askari Mirza","Hindal Mirza","Mirza Hakim"],"answer":3,"explanation":"Mirza Hakim, ruler of Kabul, advanced towards Lahore in 1581 and withdrew when Akbar marched. Kamran, Askari and Hindal were Humayun's brothers, not Akbar's.","difficulty":"hard","questionHi":"1581 में अकबर अपने सौतेले भाई से निपटने के लिए काबुल की ओर बढ़े, जिसने पंजाब पर आक्रमण किया था। वह कौन था?","optionsHi":["कामरान मिर्जा","अस्करी मिर्जा","हिंदाल मिर्जा","मिर्जा हकीम"],"explanationHi":"काबुल के शासक मिर्जा हकीम ने 1581 में लाहौर की ओर कूच किया और अकबर के आगे बढ़ने पर पीछे हट गया। कामरान, अस्करी और हिंदाल हुमायूँ के भाई थे, अकबर के नहीं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-170","question":"The Roshaniya movement among the Afghans of the north-west frontier, which clashed with Akbar's forces, was founded by:","options":["Shaikh Ahmad Sirhindi","Khwaja Baqi Billah","Bayazid Ansari","Shaikh Salim Chishti"],"answer":2,"explanation":"Bayazid Ansari (Pir Roshan) preached a mystical creed among the Yusufzai and other tribes. His movement fought the Mughals, in which Birbal was killed in 1586.","difficulty":"very-hard","questionHi":"उत्तर-पश्चिमी सीमांत के अफगानों के बीच रौशनिया आंदोलन, जिसका अकबर की सेनाओं से संघर्ष हुआ, किसने चलाया?","optionsHi":["शेख अहमद सरहिंदी","ख्वाजा बाकी बिल्लाह","बायजीद अंसारी","शेख सलीम चिश्ती"],"explanationHi":"बायजीद अंसारी (पीर रौशन) ने यूसुफजई और अन्य कबीलों में रहस्यवादी मत फैलाया। उनके आंदोलन ने मुगलों से युद्ध किया, जिसमें 1586 में बीरबल मारे गए।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-171","question":"Shaikh Ahmad Sirhindi, called Mujaddid-i-Alf-i-Sani, who opposed the liberal religious outlook of Akbar's court, belonged to the Sufi order of the:","options":["Chishti","Suhrawardi","Qadiri","Naqshbandi"],"answer":3,"explanation":"Sirhindi was a leading Naqshbandi who urged a return to orthodox Islam. Jahangir briefly imprisoned him at Gwalior.","difficulty":"hard","questionHi":"शेख अहमद सरहिंदी, जिन्हें मुजद्दिद-ए-अल्फ-ए-सानी कहा गया और जिन्होंने अकबर के दरबार के उदार धार्मिक दृष्टिकोण का विरोध किया, किस सूफी सिलसिले के थे?","optionsHi":["चिश्ती","सुहरावर्दी","कादिरी","नक्शबंदी"],"explanationHi":"सरहिंदी प्रमुख नक्शबंदी थे जिन्होंने रूढ़िवादी इस्लाम की ओर लौटने पर बल दिया। जहाँगीर ने उन्हें थोड़े समय के लिए ग्वालियर में कैद रखा।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-172","question":"Which of these Bhakti poets was a contemporary of Akbar, composing his Ramcharitmanas from about 1574?","options":["Kabir","Mirabai","Tukaram","Tulsidas"],"answer":3,"explanation":"Tulsidas (c. 1532-1623) began the Awadhi Ramcharitmanas in 1574 at Ayodhya. Kabir and Mirabai belonged to earlier times and Tukaram to the next generation in Maharashtra.","difficulty":"moderate","questionHi":"इनमें से कौन-सा भक्त कवि अकबर का समकालीन था, जिसने लगभग 1574 से अपने रामचरितमानस की रचना शुरू की?","optionsHi":["कबीर","मीराबाई","तुकाराम","तुलसीदास"],"explanationHi":"तुलसीदास (लगभग 1532-1623) ने 1574 में अयोध्या में अवधी रामचरितमानस शुरू किया। कबीर और मीराबाई पहले के समय के थे और तुकाराम महाराष्ट्र में अगली पीढ़ी के।","source":"SSC CGL · State PCS"},
  {"id":"history-mughal-173","question":"Surat, the leading Mughal port on the west coast, was known as 'Bab-ul-Makka' (Gateway to Mecca) because it was:","options":["The only port where Arab horses were landed","The main port for the embarkation of Hajj pilgrims","The seat of the Sharif of Mecca's agent in India","The place from where Mecca's mosque was supplied with timber"],"answer":1,"explanation":"Pilgrim ships to Jeddah sailed from Surat, which was also the empire's main centre of cotton textile exports. The title reflected the pilgrim traffic.","difficulty":"hard","questionHi":"पश्चिमी तट का प्रमुख मुगल बंदरगाह सूरत 'बाब-उल-मक्का' (मक्का का द्वार) क्यों कहलाता था?","optionsHi":["यह एकमात्र बंदरगाह था जहाँ अरबी घोड़े उतरते थे","यह हज यात्रियों के प्रस्थान का मुख्य बंदरगाह था","यह भारत में मक्का के शरीफ के प्रतिनिधि का निवास था","यहाँ से मक्का की मस्जिद को लकड़ी भेजी जाती थी"],"explanationHi":"जेद्दा जाने वाले तीर्थयात्री जहाज सूरत से चलते थे, जो साम्राज्य के सूती कपड़े के निर्यात का भी मुख्य केंद्र था। यह उपाधि यात्री यातायात को दर्शाती थी।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-174","question":"In the 17th century, European trade with Mughal India was financed chiefly by:","options":["Shipments of woollen cloth and iron goods to India","Silver bullion brought to pay for Indian textiles and indigo","Gold sent back from the African colonies of the Company","Barter of European horses and spices for Indian cotton"],"answer":1,"explanation":"India wanted few European goods, so the companies paid for cotton cloth, indigo, saltpetre and spices largely with silver, which increased the silver in Mughal currency.","difficulty":"hard","questionHi":"17वीं शताब्दी में मुगल भारत के साथ यूरोपीय व्यापार का वित्तपोषण मुख्यतः किससे होता था?","optionsHi":["भारत को ऊनी कपड़े और लोहे की वस्तुओं के जहाजी माल से","भारतीय वस्त्र और नील का मूल्य चुकाने के लिए लाई गई चाँदी की बुलियन से","कंपनी की अफ्रीकी बस्तियों से लौटाए गए सोने से","यूरोपीय घोड़ों और मसालों के बदले भारतीय कपास की अदला-बदली से"],"explanationHi":"भारत को यूरोपीय माल की कम आवश्यकता थी, इसलिए कंपनियाँ सूती कपड़े, नील, शोरा और मसालों का मूल्य बड़ी मात्रा में चाँदी से चुकाती थीं, जिससे मुगल मुद्रा में चाँदी बढ़ी।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-175","question":"The Mughal grant of chauth and sardeshmukhi over the six Deccan subas to Shahu (1719) was secured through an agreement of the Peshwa Balaji Vishwanath with:","options":["Zulfiqar Khan Nusrat Jang","Sayyid Husain Ali Khan","Nizam-ul-Mulk Asaf Jah","Mubariz Khan of Hyderabad"],"answer":1,"explanation":"Sayyid Husain Ali Khan, the Sayyid brother, agreed to the grant in return for Maratha military help at Delhi. Nizam-ul-Mulk and Mubariz Khan were rivals in the Deccan.","difficulty":"very-hard","questionHi":"1719 में शाहू को छह दक्कनी सूबों के चौथ और सरदेशमुखी का मुगल अनुदान पेशवा बालाजी विश्वनाथ के किसके साथ समझौते से मिला?","optionsHi":["जुल्फिकार खाँ नुसरत जंग","सैयद हुसैन अली खाँ","निजाम-उल-मुल्क आसफ जाह","हैदराबाद का मुबारिज खाँ"],"explanationHi":"सैयद बंधुओं में से हुसैन अली खाँ ने दिल्ली में मराठों की सैनिक सहायता के बदले यह अनुदान स्वीकार किया। निजाम-उल-मुल्क और मुबारिज खाँ दक्कन में प्रतिद्वंद्वी थे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-176","question":"The Rohilla chief who blinded the Mughal emperor Shah Alam II at Delhi in 1788 was:","options":["Najib-ud-Daula","Hafiz Rahmat Khan","Zabita Khan","Ghulam Qadir"],"answer":3,"explanation":"Ghulam Qadir, son of Zabita Khan and grandson of Najib-ud-Daula, seized Delhi and blinded the emperor. Mahadji Scindia's forces later punished him.","difficulty":"very-hard","questionHi":"1788 में दिल्ली में मुगल सम्राट शाह आलम द्वितीय को अंधा करने वाला रुहेला सरदार कौन था?","optionsHi":["नजीबुद्दौला","हाफिज रहमत खाँ","जाबिता खाँ","गुलाम कादिर"],"explanationHi":"जाबिता खाँ के पुत्र और नजीबुद्दौला के पौत्र गुलाम कादिर ने दिल्ली पर कब्जा कर सम्राट को अंधा किया। बाद में महादजी सिंधिया की सेना ने उसे दंड दिया।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-177","question":"The last Mughal emperor, Bahadur Shah II, was captured in September 1857 at Humayun's Tomb by:","options":["William Hodson","John Nicholson","Henry Havelock","Henry Lawrence"],"answer":0,"explanation":"Captain William Hodson took the emperor prisoner and shot his sons at Delhi. The emperor was then tried and exiled to Rangoon, where he died in 1862.","difficulty":"moderate","questionHi":"अंतिम मुगल सम्राट बहादुर शाह द्वितीय को सितंबर 1857 में हुमायूँ के मकबरे में किसने पकड़ा?","optionsHi":["विलियम हॉडसन","जॉन निकोलसन","हेनरी हैवलॉक","हेनरी लॉरेंस"],"explanationHi":"कैप्टन विलियम हॉडसन ने सम्राट को बंदी बनाया और दिल्ली में उसके पुत्रों को गोली मार दी। बाद में सम्राट पर मुकदमा चला और उन्हें रंगून निर्वासित किया गया, जहाँ 1862 में उनकी मृत्यु हुई।","source":"SSC CGL · State PCS"},
  {"id":"history-mughal-178","question":"Shah Jahan's mother, Jagat Gosain, the wife of Jahangir, was a princess of which Rajput house?","options":["Amber","Mewar","Bikaner","Marwar"],"answer":3,"explanation":"Jagat Gosain was a daughter of Udai Singh of Marwar, known as Mota Raja. This made Shah Jahan, like Jahangir, half Rajput by descent.","difficulty":"hard","questionHi":"जहाँगीर की पत्नी और शाहजहाँ की माता जगत गोसाईं किस राजपूत घराने की राजकुमारी थीं?","optionsHi":["आमेर","मेवाड़","बीकानेर","मारवाड़"],"explanationHi":"जगत गोसाईं मारवाड़ के उदय सिंह, जो मोटा राजा कहलाते थे, की पुत्री थीं। इस प्रकार शाहजहाँ, जहाँगीर की तरह, वंश से आधा राजपूत था।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-179","question":"Bairam Khan, dismissed by Akbar in 1560, was killed in 1561 at:","options":["Patan in Gujarat, on his way to Mecca","Agra, in a court conspiracy","Lahore, in a revolt against Akbar","Ajmer, while on pilgrimage to the shrine"],"answer":0,"explanation":"After his dismissal and an unsuccessful rebellion, Bairam Khan set out for Mecca and was stabbed at Patan by an Afghan. His son Abdur Rahim later became Khan-i-Khanan.","difficulty":"moderate","questionHi":"1560 में अकबर द्वारा हटाए गए बैरम खाँ की 1561 में कहाँ हत्या हुई?","optionsHi":["गुजरात के पाटन में, मक्का जाते समय","आगरा में, दरबारी षड्यंत्र में","लाहौर में, अकबर के विरुद्ध विद्रोह में","अजमेर में, दरगाह की यात्रा के समय"],"explanationHi":"पदच्युत होने और असफल विद्रोह के बाद बैरम खाँ मक्का के लिए चले और पाटन में एक अफगान ने उन्हें मार डाला। उनके पुत्र अब्दुर्रहीम बाद में खान-ए-खाना बने।","source":"SSC CGL · State PCS"},
  {"id":"history-mughal-180","question":"Aurangzeb discontinued the Kalima on Mughal coins because:","options":["He had made all coins out of copper only","The Persian script on coins could not be read by his subjects","He feared the sacred words would be defiled by handling","The Mughal mints had passed to the Marathas"],"answer":2,"explanation":"The reason given was that the Kalima would be defiled when coins passed through non-Muslim hands, so he stopped it, with the date and mint recorded instead.","difficulty":"hard","questionHi":"औरंगजेब ने मुगल सिक्कों पर कलमा अंकित करना क्यों बंद किया?","optionsHi":["उसने सभी सिक्के केवल ताँबे के बनवा दिए थे","सिक्कों की फारसी लिपि प्रजा द्वारा पढ़ी नहीं जा सकती थी","उसे डर था कि पवित्र शब्द हाथों में आने से अपवित्र होंगे","मुगल टकसालें मराठों के हाथ में चली गई थीं"],"explanationHi":"कारण यह बताया गया कि गैर-मुस्लिम हाथों से गुजरने पर कलमा अपवित्र होगा, इसलिए उसे बंद कर दिया गया और उसकी जगह तिथि और टकसाल दर्ज की गई।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-181","question":"Prince Salim, the future Jahangir, born at Sikri in 1569, was named after the Sufi saint:","options":["Salim Shah Sur","Moinuddin Chishti","Shaikh Salim Chishti","Nizamuddin Auliya"],"answer":2,"explanation":"Akbar, anxious for an heir, sought the blessing of Shaikh Salim Chishti of Sikri, and named the child after him. It led to the building of Fatehpur Sikri there.","difficulty":"moderate","questionHi":"1569 में सीकरी में जन्मे राजकुमार सलीम (भावी जहाँगीर) का नाम किस सूफी संत के नाम पर रखा गया?","optionsHi":["सलीम शाह सूर","मोईनुद्दीन चिश्ती","शेख सलीम चिश्ती","निजामुद्दीन औलिया"],"explanationHi":"उत्तराधिकारी के इच्छुक अकबर ने सीकरी के शेख सलीम चिश्ती का आशीर्वाद लिया और शिशु का नाम उन्हीं के नाम पर रखा। इसी से वहाँ फतेहपुर सीकरी का निर्माण हुआ।","source":"SSC CGL · State PCS"},
  {"id":"history-mughal-182","question":"Aurangzeb's first, informal coronation (July 1658) was held at:","options":["The Red Fort at Agra","Lahore Fort","Shalimar Bagh in Delhi","The Diwan-i-Khas at Fatehpur Sikri"],"answer":2,"explanation":"He was enthroned at the Shalimar Bagh, Delhi, after defeating Dara at Samugarh, with the formal coronation following in June 1659.","difficulty":"hard","questionHi":"औरंगजेब का पहला अनौपचारिक राज्याभिषेक (जुलाई 1658) कहाँ हुआ?","optionsHi":["आगरा का लाल किला","लाहौर का किला","दिल्ली का शालीमार बाग","फतेहपुर सीकरी का दीवान-ए-खास"],"explanationHi":"सामूगढ़ में दारा को हराने के बाद उसे दिल्ली के शालीमार बाग में गद्दी पर बैठाया गया और औपचारिक राज्याभिषेक जून 1659 में हुआ।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-183","question":"The English East India Company's war against Aurangzeb (1686-90), led by Sir John Child, ended with:","options":["The Mughals ceding Bombay to the Company in full sovereignty for ever","The Company paying a penalty and begging pardon, trade being restored by a farman in 1690","The Company's capture of Hugli and Dhaka from the Mughal governors","The Company being expelled from Surat and Bengal for good by Aurangzeb"],"answer":1,"explanation":"The Mughals seized Company factories and blockaded Bombay. The Company paid a fine, apologised and got a farman permitting trade in 1690, after which Job Charnock returned to Sutanuti.","difficulty":"very-hard","questionHi":"सर जॉन चाइल्ड के नेतृत्व में अंग्रेज ईस्ट इंडिया कंपनी का औरंगजेब के विरुद्ध युद्ध (1686-90) किस परिणाम पर समाप्त हुआ?","optionsHi":["मुगलों ने बंबई पूर्ण संप्रभुता के साथ कंपनी को दे दिया","कंपनी ने दंड चुकाकर क्षमा माँगी, जिसके बाद 1690 में फरमान से व्यापार बहाल हुआ","कंपनी ने मुगलों से हुगली और ढाका जीत लिए","कंपनी को सूरत और बंगाल से सदा के लिए निकाल दिया गया"],"explanationHi":"मुगलों ने कंपनी की कोठियाँ जब्त कीं और बंबई की नाकेबंदी की। कंपनी ने जुर्माना दिया, क्षमा माँगी और 1690 में व्यापार की अनुमति का फरमान पाया, जिसके बाद जॉब चार्नॉक सूतानुटी लौटा।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-184","question":"Which of these are accepted as causes of the jagirdari crisis of the late 17th century? 1. The number of mansabdars grew faster than the land available after the Deccan conquests. 2. The gap between the estimated income (jama) and the actual collection (hasil) widened. 3. Many mansabdars remained without jagirs (bejagiri) for long periods. 4. Aurangzeb abolished the payment of nobles through jagirs.","options":["1 and 2 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Statements 1-3 describe the crisis. Aurangzeb never ended the jagir system; the shortage of paibaqi land and the weakening of revenue collection were the problem.","difficulty":"very-hard","questionHi":"इनमें से कौन-से कारण 17वीं सदी के अंत के जागीरदारी संकट के माने जाते हैं? 1. दक्कन विजयों के बाद मनसबदारों की संख्या उपलब्ध भूमि से तेज बढ़ी। 2. अनुमानित आय (जमा) और वास्तविक वसूली (हासिल) का अंतर बढ़ गया। 3. अनेक मनसबदार लंबे समय तक बिना जागीर (बेजागीरी) रहे। 4. औरंगजेब ने अमीरों को जागीर से वेतन देने की प्रथा समाप्त कर दी।","optionsHi":["केवल 1 और 2","केवल 1, 2 और 3","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"कथन 1-3 संकट का वर्णन करते हैं। औरंगजेब ने जागीर व्यवस्था कभी समाप्त नहीं की; समस्या पाईबाकी भूमि की कमी और राजस्व वसूली की कमजोरी थी।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-185","question":"Arrange these later Mughal emperors in order of accession: 1. Jahandar Shah 2. Bahadur Shah I 3. Farrukhsiyar 4. Muhammad Shah","options":["1-2-3-4","2-1-3-4","2-1-4-3","2-3-1-4"],"answer":1,"explanation":"Bahadur Shah I (1707), Jahandar Shah (1712), Farrukhsiyar (1713) and Muhammad Shah (1719, after two short-lived rulers).","difficulty":"moderate","questionHi":"इन परवर्ती मुगल सम्राटों को गद्दी पर बैठने के क्रम में व्यवस्थित कीजिए: 1. जहाँदार शाह 2. बहादुर शाह प्रथम 3. फर्रुखसियर 4. मुहम्मद शाह","optionsHi":["1-2-3-4","2-1-3-4","2-1-4-3","2-3-1-4"],"explanationHi":"बहादुर शाह प्रथम (1707), जहाँदार शाह (1712), फर्रुखसियर (1713) और मुहम्मद शाह (1719, दो अल्पकालिक शासकों के बाद)।","source":"SSC CGL · State PCS"},
  {"id":"history-mughal-186","question":"The 'Tarikh-i-Alfi', a history of a thousand years of Islam, was commissioned by:","options":["Babur","Humayun","Akbar","Aurangzeb"],"answer":2,"explanation":"Akbar ordered it in 1582 to mark the first millennium of Islam, and a group of scholars compiled it. It was an early attempt at a collective history project.","difficulty":"hard","questionHi":"इस्लाम के एक हजार वर्षों का इतिहास 'तारीख-ए-अल्फी' किसके आदेश से लिखा गया?","optionsHi":["बाबर","हुमायूँ","अकबर","औरंगजेब"],"explanationHi":"अकबर ने इस्लाम की प्रथम सहस्राब्दी के उपलक्ष्य में 1582 में इसका आदेश दिया और विद्वानों के एक दल ने इसे संकलित किया। यह सामूहिक इतिहास-परियोजना का आरंभिक प्रयास था।","source":"UPSC Prelims · State PCS"},
  {"id":"history-mughal-187","question":"Among Akbar's nobles, the only Hindu who is recorded as having joined the Din-i-Ilahi was:","options":["Man Singh","Todar Mal","Bhagwan Das","Birbal"],"answer":3,"explanation":"Birbal alone among the Hindu courtiers is named as a follower. Man Singh and Bhagwan Das are said to have declined, and the order never had more than a handful of members.","difficulty":"moderate","questionHi":"अकबर के अमीरों में एकमात्र हिंदू, जिसके दीन-ए-इलाही में सम्मिलित होने का उल्लेख है, कौन था?","optionsHi":["मानसिंह","टोडरमल","भगवानदास","बीरबल"],"explanationHi":"हिंदू दरबारियों में केवल बीरबल को अनुयायी बताया गया है। मानसिंह और भगवानदास ने इसे अस्वीकार किया माना जाता है और इस पंथ के सदस्य मुट्ठी भर ही रहे।","source":"SSC CGL · State PCS"},
];

export default questions;
